window.courseSearchIndex = [{"topic": "mac", "topicName": "把 Mac 用顺", "audience": "mom", "audienceName": "妈妈", "number": 0, "title": "把 Mac 用顺", "step": "专题介绍", "text": "Mac 基础与家庭协作 从开箱、装软件到邮件、会议和家庭共享，先把这台 Mac 用顺。 ", "url": "topics/mac/index.html", "status": "active"}, {"topic": "mac", "topicName": "把 Mac 用顺", "audience": "mom", "audienceName": "妈妈", "number": 1, "title": "把新 Mac 设置到能上远程课", "step": "1. 新 Mac 联网后先装豆包桌面版", "text": "本课按 macOS 27 编写。 接电开机，按提示设置 Mac 登录密码并连网，打开 Safari。 打开 下载豆包桌面版（Mac） ，选 Mac 版。下载后在 Finder 的「下载」里打开安装文件，按提示安装。从「应用程序」打开豆包并登录。 在豆包桌面客户端先拨通语音通话，再从通话界面开启屏幕共享。若 macOS 提示授权，按提示在「系统设置 → 隐私与安全性」为豆包开启麦克风和屏幕录制相关权限（名称随 macOS 版本变化，例如「录屏与系统录音」），必要时重新打开客户端。按钮名称以现场版本为准。 打开「系统设置」，对着 Mac 说：「请看我现在共享的画面。我想检查系统更新，请只告诉我下一步。」妈妈自己照着点，再让豆包按新画面给下一步。按豆包的说明，它会在收到指令时截取当时的共享画面。 豆包隐私政策 做完停止共享并结束通话。进入账号验证或私人页面前先停共享。若通话或共享入口暂时不可用，记下卡点，先继续设置，第 2 讲再补验收。", "url": "topics/mac/01-new-mac.html#step-1", "status": "active"}, {"topic": "mac", "topicName": "把 Mac 用顺", "audience": "mom", "audienceName": "妈妈", "number": 1, "title": "把新 Mac 设置到能上远程课", "step": "2. 检查更新，先把下载排起来", "text": "本课按 macOS 27 编写。 打开「系统设置 → 通用 → 软件更新」。若安装需要重启，先看看等待时间。今天优先保证腾讯会议能入会，可先启动下载，或等入会测试后再重启。更新结束后重新检查这一页。 从 Safari 打开 下载腾讯会议（Mac） ，选 macOS，先下载它。打开 Safari 的下载列表或 Finder 的「下载」目录，确认文件已下载完成。 同时从 MacTeX 下载页 找到 MacTeX 安装包。它是大文件，网络和磁盘空间允许时让它先下载，等候期间做下面的设置。如果网络慢，先保腾讯会议和系统更新，MacTeX 可留在课间继续。 用同样方法找到 Chrome 和 微信 Mac 版 。优先下载后面马上用到的微信和 Chrome。DeepSeek Harness 留到妈妈开始 AI 课程时再按当时的官方入口安装。官方下载或使用入口暂时不可用时，记下卡在哪一步，继续其他项目。", "url": "topics/mac/01-new-mac.html#step-2", "status": "active"}, {"topic": "mac", "topicName": "把 Mac 用顺", "audience": "mom", "audienceName": "妈妈", "number": 1, "title": "把新 Mac 设置到能上远程课", "step": "3. 登录 Apple 账户，检查 App Store 更新", "text": "本课按 macOS 27 编写。 打开「系统设置」，点左上方 Apple 账户入口，用自己的账户登录并在自己的设备上完成验证。 打开账户下的 iCloud 页面，核对日历、备忘录和照片等本次要使用的同步项目。家庭共享邀请与应用里的实际显示在第 3 讲检查。邮箱账户在第 2 讲另行添加。 打开 App Store，点边栏的「更新」。如有待更新的应用，先更新马上要用的。其余在网络空闲时继续。回到更新页确认所选项目已完成。系统更新负责 Safari、备忘录等系统内建 App 的更新。App Store 的「更新」针对从商店获得的 App。", "url": "topics/mac/01-new-mac.html#step-3", "status": "active"}, {"topic": "mac", "topicName": "把 Mac 用顺", "audience": "mom", "audienceName": "妈妈", "number": 1, "title": "把新 Mac 设置到能上远程课", "step": "4. 安装腾讯会议，并亲手进会", "text": "本课按 macOS 27 编写。 在 Finder 的「下载」打开官方安装文件。若是 .dmg ，先打开，再看里面是可拖入「应用程序」的 App，还是要双击运行的安装器。若是 .pkg ，双击后按安装器的提示继续。 到 Finder 的「应用程序」打开腾讯会议。点家人发的测试邀请，开关麦克风，请对方确认声音。选择一个练习窗口共享，再停止。若被要求授予权限，按提示到「系统设置 → 隐私与安全性」检查麦克风或屏幕录制权限，按应用提示重新打开并试一次。 退出会议，再用原邀请重新进会。Mac 还在更新时，先用手机验证能加入，再把 Mac 入会留作待办。 打开「文本编辑」，写一行测试文字，试 ⌘C 复制、 ⌘V 粘贴、 ⌘S 保存。把文件存到「文稿」，关闭后用 Finder 找回。 本节以能入会为优先。豆包试一次即可，其余软件先排下载，来不及就到第 2 讲再安装。给每项软件记一个状态：待下载、下载中、已安装、已打开验证。 备查： Apple 软件更新 · App Store 手动更新 · Apple 隐私与安全设置 · 腾讯会议桌面端指南 · DeepSeek 平台常见问题", "url": "topics/mac/01-new-mac.html#step-4", "status": "active"}, {"topic": "mac", "topicName": "把 Mac 用顺", "audience": "mom", "audienceName": "妈妈", "number": 2, "title": "验收应用，配好邮箱并核对同步", "step": "检查应用和远程入会", "text": "从上节链接进会。打开「下载」目录，逐项检查上节的状态。先完成系统重启和腾讯会议验证，再继续安装。 Chrome ：打开官方安装文件，按窗口提示放入「应用程序」，再从那里打开，访问一个已知网页。 微信 ：同样打开官方安装文件，安装后从「应用程序」打开，按提示用手机确认登录。先检查能看到聊天列表。 复用 Mac 版豆包 ：在 Mac 上发起豆包语音通话并共享练习画面，问「请看我现在的画面。我想找到邮件的获取设置，下一步点哪里？」照建议做一步，再停止共享。进入真实账户页面前先停共享。上节若没走通，先补麦克风和屏幕共享。 MacTeX ：下载结束后，从「下载」双击官方 .pkg ，按安装器提示继续。成功后打开「应用程序」里的 TeX 工具目录，尝试启动 TeXShop。若仍在下载，就先做邮件。", "url": "topics/mac/02-apps-and-email.html#step-1", "status": "active"}, {"topic": "mac", "topicName": "把 Mac 用顺", "audience": "mom", "audienceName": "妈妈", "number": 2, "title": "验收应用，配好邮箱并核对同步", "step": "添加邮箱并验证同步", "text": "添加网易 126 邮箱。 打开苹果「邮件 → 添加账户」，输入妈妈完整的 @126.com 邮箱地址。已添加的账号可在「邮件 → 设置 → 账户」查看。 如果验证失败，检查客户端授权。 打开 网易 126 网页邮箱 并登录。在设置中找 POP3/SMTP/IMAP 或客户端授权相关选项，按网页提示检查 IMAP/SMTP 并生成授权码。先停止屏幕共享，再由妈妈将授权码填入苹果「邮件」的密码栏。菜单名称以实际账户界面为准。 网易邮箱帮助 验证双向同步。 从苹果「邮件」发一封测试邮件，在 126 网页邮箱的「已发送」里找同一主题。请家人回复，再回苹果「邮件」查看回信。需要调整检查频率时，打开「邮件 → 设置 → 通用 → 检查新邮件」。 快捷键和触控板集中放到第 3 讲。 做不完时，先确保会议和邮件可用，记录还没验证的软件和动作。 备查： Apple 添加邮件账户 · Apple 邮件通用设置 · MacTeX 的 TeXShop 位置", "url": "topics/mac/02-apps-and-email.html#step-2", "status": "active"}, {"topic": "mac", "topicName": "把 Mac 用顺", "audience": "mom", "audienceName": "妈妈", "number": 3, "title": "练快捷键、触控板与家庭共享", "step": "快捷键和触控板", "text": "打开测试文稿，逐项试 ⌘C 复制、 ⌘V 粘贴、 ⌘S 保存、 ⌘W 关窗口、 ⌘Q 退出、 ⇧⌘4 区域截图。打开触控板设置，在「更多手势」看本机演示。练上滑打开「调度中心」、左右滑切换全屏 App 或桌面空间、拇指与三指张开显示桌面。若本机有「启动台」捏合手势再试它。没有这个选项就用聚焦查找并打开 App。", "url": "topics/mac/03-shortcuts-and-sharing.html#step-1", "status": "active"}, {"topic": "mac", "topicName": "把 Mac 用顺", "audience": "mom", "audienceName": "妈妈", "number": 3, "title": "练快捷键、触控板与家庭共享", "step": "验证日历、备忘录和相簿", "text": "快捷操作试过后，再检查家庭共享。当天来不及就从下一个项目接着做。 打开苹果「日历」，找一条家人已经共享的日程。新建一个有开始和结束时间的测试日程，选家人共享且自己有编辑权限的 iCloud 日历，请家人在另一台设备确认能看到。 用自己的 Apple 账户开启 iCloud 备忘录，接受共享邀请，再在「备忘录」的 iCloud 列表找之前共享的三条。看不到时，核对邀请所用的邮件地址或电话号码是否关联到自己的 Apple 账户。打开课程使用计划和另外两条家庭备忘录，确认正文能显示。真实名称由家人现场确认。 家里用的是 Apple「共享相簿」。在 macOS 27 的「照片 → 设置 → iCloud」检查「iCloud 照片」和「共享相簿」已开启。接受家人的相簿邀请后，在「照片」边栏的「共享」部分找到相簿，打开一张家人分享的照片。 Apple 共享相簿指南 遇到陌生菜单，可以在 Mac 版豆包里发起语音通话并共享练习画面，再问一小步。共享日历是否同步，以家人在自己设备上看到的结果为准。 备查： Apple 键盘快捷键 · 触控板手势 · 共享日历 · 备忘录协作 · 共享相簿 · 共享照片图库", "url": "topics/mac/03-shortcuts-and-sharing.html#step-2", "status": "active"}, {"topic": "mac", "topicName": "把 Mac 用顺", "audience": "mom", "audienceName": "妈妈", "number": 4, "title": "会议预约、语音输入与 MacTeX", "step": "预定会议并同步日历", "text": "先补前几节没完成、今天会用到的项目。腾讯会议、微信和 Apple 账户能打开后，再做下面的练习。 在腾讯会议 Mac 客户端主页点「预定会议」，填主题和时间，再点「预定」。从会议详情或邀请菜单复制会议号和链接。把日期、时区与链接通过邮件发给约好的家人，请对方核对在哥本哈根看到的时间。 在苹果「日历」建立测试日程，用日程右上角的彩色标记选一个自己可编辑的共享日历。双击日程，在「添加备注、URL 或附件」贴入会议链接。需要指定时区时，在「日历 → 设置 → 高级」打开时区支持，再点日程日期选择上海时区。请家人在哥本哈根用自己的设备核对当地开始时间，并打开链接确认是同一场会议。 Apple 添加和修改日程", "url": "topics/mac/04-meetings-and-mactex.html#step-1", "status": "active"}, {"topic": "mac", "topicName": "把 Mac 用顺", "audience": "mom", "audienceName": "妈妈", "number": 4, "title": "会议预约、语音输入与 MacTeX", "step": "试微信语音转文字", "text": "先补前几节没完成、今天会用到的项目。腾讯会议、微信和 Apple 账户能打开后，再做下面的练习。 优先练微信 Mac 客户端自带的语音转文字。打开一个测试聊天，把光标放在输入框，找语音输入的小话筒或客户端显示的快捷键。试说「明天给薄荷浇水，check the leaves」。确认中英文出现在可编辑的输入框，核对后清空。入口以现场客户端版本为准。如果只有发送语音消息的按钮，先请家人一起检查版本和设置。macOS 听写作为备用，可在「系统设置 → 键盘 → 听写」查看启用方式和快捷键。", "url": "topics/mac/04-meetings-and-mactex.html#step-2", "status": "active"}, {"topic": "mac", "topicName": "把 Mac 用顺", "audience": "mom", "audienceName": "妈妈", "number": 4, "title": "会议预约、语音输入与 MacTeX", "step": "验证 MacTeX", "text": "先补前几节没完成、今天会用到的项目。腾讯会议、微信和 Apple 账户能打开后，再做下面的练习。 本节只用 Mac 上已经装好的 TeXShop，不需要 DeepSeek Harness。 下载 中文手册练习项目（ZIP） 和 测试文件 。把 ZIP 解压到「文稿」，测试文件也放到同一个「文稿」位置。 双击测试文件，TeXShop 会打开它。点工具栏的「排版」（Typeset），等预览窗口出现。若能看到「MacTeX 练习」和下面那行中文，说明中文编译环境可用。 在 TeXShop 里打开解压后的 chinese-manual/main.tex 。文件第一行指定 XeLaTeX，按「排版」编译；第一次目录可能为空，再按一次「排版」更新目录。 在预览里核对封面、目录，以及「准备设备」「记录与复查」两个中文章节。看到本次生成的 PDF 就完成本节验证；妈妈本节不做 PDF 批注。 若排版报错，先看 TeXShop 日志窗口的第一条错误，记下文件名和提示。确认 MacTeX 已安装、TeXShop 是从「应用程序」打开的；修不了就记下错误，下节课一起看。 如仍有待完成的基础操作，记下从哪一步接着做。豆包桌面版继续按需使用。工具选择与提示词的系统练习留到第 5、6 节。 备查： 腾讯会议预定常规会议 · Apple 听写设置 · MacTeX 图形工具", "url": "topics/mac/04-meetings-and-mactex.html#step-3", "status": "active"}, {"topic": "ai", "topicName": "和 AI 一起做事", "audience": "both", "audienceName": "共同", "number": 0, "title": "和 AI 一起做事", "step": "专题介绍", "text": "从提问到 DeepSeek Harness 先分清界面和模型，再用自己的账户跑通 Codex、Harness 和用量核对。 ", "url": "topics/ai/index.html", "status": "active"}, {"topic": "ai", "topicName": "和 AI 一起做事", "audience": "both", "audienceName": "共同", "number": 1, "title": "认识两层 AI，用自己的账户跑通 Codex", "step": "1. 用两层来理解 AI", "text": "界面是操作入口。 你打开 Codex，在里面输入任务。 模型负责生成回答。 这台 Mac 的 Codex 接的是 DeepSeek。 界面把结果显示给你。 先试一句简单的问题，看看能否收到回复。 最后自己核对。 如果问的是事实，就对照原文。如果问的是操作，就亲手试一步。 flowchart LR A[你输入任务] --> B[Codex 界面] B --> C[DeepSeek 模型] C --> D[界面显示回答] 备查：在中国大陆，普通对话用当地可用的 DeepSeek 入口。本地 Codex 接入是否正常，用测试请求和 DeepSeek 账户用量核对。 OpenAI 服务支持地区", "url": "topics/ai/01-models-and-tools.html#step-1", "status": "active"}, {"topic": "ai", "topicName": "和 AI 一起做事", "audience": "both", "audienceName": "共同", "number": 1, "title": "认识两层 AI，用自己的账户跑通 Codex", "step": "2. 用自己的 DeepSeek 账户跑通 Codex", "text": "今天要做的是亲手从「有自己的账户」走到「在 Codex 收到一条回复，并能回开放平台找这次用量」。 登录开放平台。 在浏览器打开 DeepSeek 开放平台 ，注册或登录自己的账户，按页面完成验证。打开账户余额和用量页面，记下测试前的余额与时间。 小额充值。 进入充值页面，先核对金额和账户。若页面允许，充约 10 元作为练习预算，支付后回到账户页确认余额。以页面实际可选金额为准，金额不合适就把这一步留待确认。 创建 API Key。 在「API Keys」创建一把专用于这台 Mac 的密钥，可命名为 my-codex 。它像给这个工具使用账户的一把钥匙。创建时在本机妥善保存。暂停屏幕共享，密钥只填入本机接入配置，避开聊天输入框、截图和课程仓库。 把新密钥接到已跑通的 Codex。 和家人一起确认这台 Mac 现有 DeepSeek 接入方式及密钥存放位置，保留可恢复的原设置，再把接入所用的密钥换成自己新建的那把。模型和接入地址先沿用已验证的配置。DeepSeek 官方方案使用 Responses API，配置示例将密钥存于本机配置文件。实际换密钥前先核对本机接入方式，勿共享配置文件或把备份存进课程目录。改好后完全退出桌面应用、重新打开 Codex，确认当前使用 DeepSeek 配置。若发现本机配置与预期不同，先按 DeepSeek 官方 Codex 接入说明 核对，再决定是否调整现有配置。 发一条短测试。 在 Codex 新对话输入「请只回复：连接成功。」看到回复后记下发送时间。若提示认证失败，先核对密钥和当前配置。若提示余额不足，回开放平台检查余额。先修正原因，再发下一次测试。 回开放平台核对。 打开用量明细，选测试当天，若页面提供按 API Key 筛选，就选新建密钥和测试日期。用当时可见的时间、模型和用量粒度核对，页面只有汇总时就比较测试前后。读一读页面实际提供的输入、输出 token 和费用。Token 是模型处理文字时用的小单位，和屏幕上看到的字数可以不同。余额只显示到有限位数时，优先看用量明细。若暂时没看到记录，记下测试时间和密钥名称，下次刷新再查。 首课优先走到收到测试回复。用量还没核对到，或注册、支付、接入中途停住，就在第 2 讲配置 Harness 前补齐。", "url": "topics/ai/01-models-and-tools.html#step-2", "status": "active"}, {"topic": "ai", "topicName": "和 AI 一起做事", "audience": "both", "audienceName": "共同", "number": 1, "title": "认识两层 AI，用自己的账户跑通 Codex", "step": "3. 从手头的事挑入口", "text": "想做什么 先试哪个入口 一个生活例子 边看着 Mac 边问怎么操作 豆包 Mac 客户端的语音通话与屏幕共享 「怎么在 Finder 里快速看一眼照片？」 问问题、想办法、先看一段文字 在大陆优先用可用的 DeepSeek 或 Kimi 对话入口 「把这三件事写成一条发给家人的周末提醒。」 给一个练习项目做出或修改具体文件 Codex 「在练习目录新建一个能在浏览器打开的家庭菜单网页。」 把几份材料交给工作助手整理成一个成果 了解 ChatGPT Work 和 Kimi Work 「把几份虚构菜谱整理成一张分类表。」首课认识用途即可。 这里按学习场景选入口。有的工具能做相似的事，课堂上先用最容易开始的那个。Codex 云端执行是运行位置的概念，和 ChatGPT Work 这样的工作入口分别理解即可。", "url": "topics/ai/01-models-and-tools.html#step-3", "status": "active"}, {"topic": "ai", "topicName": "和 AI 一起做事", "audience": "both", "audienceName": "共同", "number": 1, "title": "认识两层 AI，用自己的账户跑通 Codex", "step": "收尾", "text": "用一句话说出「我打开的是哪个工具，背后用的是哪个模型」。再从上表选一个自己平时会遇到的场景，说说为什么会先打开那个工具。第 2 讲配置 DeepSeek Harness，第 3 讲再做生活提示词实操。 备查： OpenAI Docs 提示词指南 · Kimi Work 官方介绍 · DeepSeek 官方文档", "url": "topics/ai/01-models-and-tools.html#step-4", "status": "active"}, {"topic": "ai", "topicName": "和 AI 一起做事", "audience": "both", "audienceName": "共同", "number": 1, "title": "认识两层 AI，用自己的账户跑通 Codex", "step": "妈妈清单", "text": "这一讲两人用同一份内容，账户、密钥和登录都用自己的。 用自己的话说出「界面」和「模型」的分工。 注册或登录自己的 DeepSeek 开放平台账户，按页面提示小额充值。 创建自己的 API Key，接到这台 Mac 的 Codex 上，发一条测试，再回开放平台核对用量。这台 Mac 还没有 Codex 时，和家人一起按这一讲的入口装好。 记下卡住的一步，下一讲用 Harness 继续。", "url": "topics/ai/01-models-and-tools.html#step-5", "status": "active"}, {"topic": "ai", "topicName": "和 AI 一起做事", "audience": "both", "audienceName": "共同", "number": 2, "title": "初始化 Harness，装输入法和六个插件", "step": "1. 安装并初始化 DeepSeek Harness", "text": "这一节不做网站、不编译 LaTeX，也不验证批注工作流。目标只有一个：把以后要用的 DeepSeek Harness 环境准备齐，并用安装清单逐项核对。 打开 DeepSeek Harness 官方发布页 ，在所选版本的 Assets 中找适用于 macOS Apple Silicon 的桌面安装文件，安装到「应用程序」并打开。发布页若只显示源码或找不到对应安装文件，先核对家里已安装的桌面版及其更新入口，再继续本课。 沿用 第 1 讲 使用的 DeepSeek 开放平台账户。在 Harness 的模型设置中配置自己的 API Key。远程上课时先停止屏幕共享，再由本人粘贴密钥；密钥不放进聊天、截图或课程仓库。 打开模型选择器，确认能看到 DeepSeek 提供方和可选模型。模型、推理强度和用量统一放到第 3 讲练。 DeepSeek Harness 模型配置说明 · DeepSeek 开放平台", "url": "topics/ai/02-harness-setup.html#step-1", "status": "active"}, {"topic": "ai", "topicName": "和 AI 一起做事", "audience": "both", "audienceName": "共同", "number": 2, "title": "初始化 Harness，装输入法和六个插件", "step": "2. 安装微信输入法", "text": "这一节不做网站、不编译 LaTeX，也不验证批注工作流。目标只有一个：把以后要用的 DeepSeek Harness 环境准备齐，并用安装清单逐项核对。 打开 微信输入法官网 ，下载并安装 macOS 版。 在「系统设置 → 键盘 → 文字输入」确认微信输入法已经加入输入法列表；按系统提示授予麦克风权限。 找到微信输入法的语音输入快捷键并记下来。今天只确认安装和入口，不在 Harness 里口述任务，也不另外安装 Harness 的语音输入插件。", "url": "topics/ai/02-harness-setup.html#step-2", "status": "active"}, {"topic": "ai", "topicName": "和 AI 一起做事", "audience": "both", "audienceName": "共同", "number": 2, "title": "初始化 Harness，装输入法和六个插件", "step": "3. 先装插件市场", "text": "这一节不做网站、不编译 LaTeX，也不验证批注工作流。目标只有一个：把以后要用的 DeepSeek Harness 环境准备齐，并用安装清单逐项核对。 在 Harness 的插件设置中安装并启用 dshmarket 。重开 Harness 后，确认可以进入可视化插件市场。插件入口和按钮名称以你这台电脑上的版本为准。", "url": "topics/ai/02-harness-setup.html#step-3", "status": "active"}, {"topic": "ai", "topicName": "和 AI 一起做事", "audience": "both", "audienceName": "共同", "number": 2, "title": "初始化 Harness，装输入法和六个插件", "step": "4. 安装另外五个指定插件", "text": "这一节不做网站、不编译 LaTeX，也不验证批注工作流。目标只有一个：把以后要用的 DeepSeek Harness 环境准备齐，并用安装清单逐项核对。 在插件市场按下表的界面显示名称逐项搜索和安装。每装一个就回到 Installed plugins 清单核对名称，并确认右侧开关已开启。搜索不到时记录本机版本和搜索结果，课上一起核对安装入口。 插件市场能打开后，可以在 Harness 会话中输入下面的任务。先看它实际能使用哪些插件管理工具，以及列出的已安装状态，再让它逐项继续。 请帮我准备这六个 DeepSeek Harness 插件：dshmarket、HTML Annotations、Config Sync、dsh-image-gen、dsh-quote-annotate-pro、dsh-workspace-folders。 先检查 Installed plugins，按这六个显示名称列出「已安装并启用／已安装但未启用／未找到」，再告诉我当前会话能否调用安装或启用插件的工具。不要安装 dsh-ears。 如果能操作插件，请逐项安装或启用缺少的插件。每完成一项就重新查看 Installed plugins，报告显示名称和开关状态；需要我在界面确认时停下来。 如果当前会话没有安装能力，请只告诉我在插件页逐项搜索和核对的步骤，不要声称已经安装。 对照自己的 Installed plugins 清单核对六项。若 Harness 无法在会话中安装，就在插件页按清单逐项完成；界面显示的版本与来源以本机确认框为准。 DeepSeek Harness 插件索引说明 Installed plugins 中的显示名称 以后负责什么 HTML Annotations 在 Harness 预览的 HTML 页面上定位并提交批注 Config Sync 导出或迁移 Harness 配置与插件设置 dsh-image-gen 以后需要时接入图像生成服务 dsh-quote-annotate-pro 在 PDF、Markdown 和代码预览中做精确划词批注 dsh-workspace-folders 给工作区增加额外的工作目录 不安装 dsh-ears 。语音输入统一使用微信输入法。", "url": "topics/ai/02-harness-setup.html#step-4", "status": "active"}, {"topic": "ai", "topicName": "和 AI 一起做事", "audience": "both", "audienceName": "共同", "number": 2, "title": "初始化 Harness，装输入法和六个插件", "step": "5. 用清单收尾", "text": "这一节不做网站、不编译 LaTeX，也不验证批注工作流。目标只有一个：把以后要用的 DeepSeek Harness 环境准备齐，并用安装清单逐项核对。 [ ] DeepSeek Harness 可以打开，模型设置里已保存自己的 DeepSeek 配置。 [ ] 微信输入法已安装，能在菜单栏切换，并已找到语音输入入口。 [ ] dshmarket 已安装并启用。 [ ] HTML Annotations 已安装并启用。 [ ] Config Sync 已安装并启用。 [ ] dsh-image-gen 已安装并启用。 [ ] dsh-quote-annotate-pro 已安装并启用。 [ ] dsh-workspace-folders 已安装并启用。 今天不要求这些插件真正完成任务。若某个插件因版本不相容而无法启用，记下显示名称、版本和报错，其他项目继续安装。", "url": "topics/ai/02-harness-setup.html#step-5", "status": "active"}, {"topic": "ai", "topicName": "和 AI 一起做事", "audience": "both", "audienceName": "共同", "number": 2, "title": "初始化 Harness，装输入法和六个插件", "step": "妈妈清单", "text": "这一节不做网站、不编译 LaTeX，也不验证批注工作流。目标只有一个：把以后要用的 DeepSeek Harness 环境准备齐，并用安装清单逐项核对。 这一讲两人同一份清单，账户和密钥用自己的。 完成 Harness 安装、模型设置和一条「连接成功」测试。 安装微信输入法，找到语音输入快捷键。 安装插件市场 dshmarket 和另外五个指定插件，逐项核对 Installed plugins 的开关。 不安装 dsh-ears ；语音输入统一用微信输入法。卡住时记下显示名称、版本和报错，下一讲继续。", "url": "topics/ai/02-harness-setup.html#step-6", "status": "active"}, {"topic": "ai", "topicName": "和 AI 一起做事", "audience": "both", "audienceName": "共同", "number": 3, "title": "比较推理强度，读网页和日历", "step": "1. 先认清模型与推理强度", "text": "第 2 讲已经完成 Harness、微信输入法和插件安装。这节在 DeepSeek Harness 中练习模型、推理强度和开放平台用量，再用已验证的浏览器与日程工具完成一项真实查询。 打开 DeepSeek Harness，新建一个空练习会话。 打开模型选择器，确认提供方是 DeepSeek，并记下当前模型名。模型列表以本机实际显示为准；若能选择 deepseek-flash 和 deepseek-v4-pro ，先用 Flash 做简单练习，需要更复杂推理时再比较 Pro。 找到 Effort 或推理强度。Harness 的 DeepSeek 直连可能显示 off 、 low 、 high 、 max 。先说出它控制的是「模型愿意投入多少推理」，不是文件权限，也不会自动开启联网搜索。 复杂问题不一定总要最高档。简单整理先用低档；条件多、需要比较时再提高，并通过结果判断是否值得。 DeepSeek Harness 模型配置说明 · DeepSeek 思考模式", "url": "topics/ai/03-effort-and-usage.html#step-1", "status": "active"}, {"topic": "ai", "topicName": "和 AI 一起做事", "audience": "both", "audienceName": "共同", "number": 3, "title": "比较推理强度，读网页和日历", "step": "2. 用同一道题比较两个档位", "text": "第 2 讲已经完成 Harness、微信输入法和插件安装。这节在 DeepSeek Harness 中练习模型、推理强度和开放平台用量，再用已验证的浏览器与日程工具完成一项真实查询。 在两个新会话里使用同一个模型和完全相同的问题，只改变推理强度。下面用虚构行程练习，比较时不要改动提示词中的条件。 我要安排一次半天家庭出行。两位长辈不想走太多路，上午 9:30 从上海长宁区出发，12:30 前回家。 请先列出你还缺少的三个关键信息，再给一份暂定安排。 交通时间未经核实的地方请标「待核实」。最后列出我需要亲自核对的两件事。 第一次选择 low ；记录发送时间、回复所用时间、追问是否有针对性，以及有没有忽略条件。 第二次选择 high 或 max ；其余内容不变，再记录同样四项。 把两次结果并排看。重点不是哪一份更长，而是哪一份更准确地使用了条件、清楚区分了待核实信息。 做自己的出行安排时，可以替换人数、出发地和时间。比较两个推理档位时，两次仍须使用完全相同的文字。", "url": "topics/ai/03-effort-and-usage.html#step-2", "status": "active"}, {"topic": "ai", "topicName": "和 AI 一起做事", "audience": "both", "audienceName": "共同", "number": 3, "title": "比较推理强度，读网页和日历", "step": "3. 回开放平台找这两次用量", "text": "第 2 讲已经完成 Harness、微信输入法和插件安装。这节在 DeepSeek Harness 中练习模型、推理强度和开放平台用量，再用已验证的浏览器与日程工具完成一项真实查询。 打开 DeepSeek 开放平台 的用量或账单页面，选当天和自己用于 Harness 的 API Key。 对照刚才记录的时间，观察平台能否区分两次请求。页面显示哪些字段就读哪些字段，例如输入 token、输出 token、思考 token、缓存或费用；不要用屏幕字数猜 token。 记录两次请求能确认的模型、档位、耗时和用量。若明细延迟出现，先记下时间，稍后刷新，不重复发送许多测试。 说出结论：「高档是否更慢？是否用了更多 token？这道题的答案是否真的更好？」一次练习只说明本次任务，不代表所有问题。 DeepSeek Token 用量说明 · DeepSeek 定价页", "url": "topics/ai/03-effort-and-usage.html#step-3", "status": "active"}, {"topic": "ai", "topicName": "和 AI 一起做事", "audience": "both", "audienceName": "共同", "number": 3, "title": "比较推理强度，读网页和日历", "step": "4. 用微信输入法口述一条真实提示词", "text": "第 2 讲已经完成 Harness、微信输入法和插件安装。这节在 DeepSeek Harness 中练习模型、推理强度和开放平台用量，再用已验证的浏览器与日程工具完成一项真实查询。 从机票、商品比价或上海便民信息中挑一个需求，用微信输入法口述进 Harness。先用公开网页练浏览器读取。可以按自己的兴趣改成另一项公开政策，仍要求它给出原文链接和待核实之处。 上海市人民政府 请用当前可用的浏览器工具，在上海市人民政府网站找一条与长者服务有关的公开办事指南。 给出标题、发布单位、发布日期、正文链接和一条适用条件，并指出支持这条条件的正文位置。 先报告你实际打开了哪些页面、读到了哪些正文。只看到搜索摘要或读不到正文时请说明，不要补猜。 我会打开原链接，核对域名、日期和适用条件。 打开同一链接，核对域名、日期与适用条件，并查看 Harness 是否确实调用了浏览器。若工具打不开正文，就自己打开官方页面，把可公开的段落复制进会话，让 Harness 只根据这段文字整理。 再用一条测试日程练习只读本机日历。先在已授权的日历中新建一条标题为「家庭出行测试」的练习日程，设置当天的开始、结束时间并记下来，再发送下面的提示词。若日历只有读取权限，就请有权限的家人创建这条测试日程。 请只读取我当前已授权日历里标题为「家庭出行测试」的那条测试日程，不要创建或修改日程。 报告它的日期、开始和结束时间、时区，并按时间顺序整理成一行行程。 如果找不到、遇到多条同名日程或看不到时区，请说明实际查到什么，再问我下一步。 我会回到日历原记录，逐项核对。 对照日历原记录核对时间和时区。若读取失败，记录日历名称和权限提示，先完成网页练习。想换成机票或商品比价时，可以把目标、日期或型号、预算、希望读取的公开来源写进同样的提示词，要求列出实际打开的页面和无法确认的价格或规格。登录、提交资料、下单和付款由本人操作。", "url": "topics/ai/03-effort-and-usage.html#step-4", "status": "active"}, {"topic": "ai", "topicName": "和 AI 一起做事", "audience": "both", "audienceName": "共同", "number": 3, "title": "比较推理强度，读网页和日历", "step": "收尾", "text": "第 2 讲已经完成 Harness、微信输入法和插件安装。这节在 DeepSeek Harness 中练习模型、推理强度和开放平台用量，再用已验证的浏览器与日程工具完成一项真实查询。 完成时，你应能在 Harness 里指出模型名和 Effort，从开放平台找到至少一条对应的用量记录，并对照实际调用与原页面或日历核对一项结果。", "url": "topics/ai/03-effort-and-usage.html#step-5", "status": "active"}, {"topic": "ai", "topicName": "和 AI 一起做事", "audience": "both", "audienceName": "共同", "number": 3, "title": "比较推理强度，读网页和日历", "step": "妈妈清单", "text": "第 2 讲已经完成 Harness、微信输入法和插件安装。这节在 DeepSeek Harness 中练习模型、推理强度和开放平台用量，再用已验证的浏览器与日程工具完成一项真实查询。 这一讲两人同一份内容，用同一道虚构题比较推理强度。 在 Harness 里找到模型名和 Effort。 用这一讲的虚构行程题，分别用 low 和 high/max 各做一次。 回 DeepSeek 开放平台核对两次请求的用量。 用微信输入法口述一条提示词，按这一讲读一条公开网页；日历只读，不创建或修改日程。", "url": "topics/ai/03-effort-and-usage.html#step-6", "status": "active"}, {"topic": "word-to-latex", "topicName": "把技术文档做成书", "audience": "dad", "audienceName": "爸爸", "number": 0, "title": "把技术文档做成书", "step": "专题介绍", "text": "从 Word 到可维护的中文 LaTeX 把一份真实的 Word 技术文档逐步变成可编译、可修改、可复用的中文 LaTeX 项目。 ", "url": "topics/word-to-latex/index.html", "status": "active"}, {"topic": "word-to-latex", "topicName": "把技术文档做成书", "audience": "dad", "audienceName": "爸爸", "number": 1, "title": "说清 Word 转 LaTeX 的目标", "step": "1. 指出项目的输入", "text": "我们已经选定第一份项目：把一份一百多页的中文 Word 技术文档忠实转换成 LaTeX。排版模板将在第 3 讲由爸爸从 Overleaf 选定，再改造成可复用的中文多章节模板。今天先把已确定的输入、预期产出和学习目标写成一页项目说明；公开课稿只用占位名称。 在 Finder 找到 Word 原件并打开，确认这就是要转换的技术文档。公开课稿用 source-document.docx 作占位名称；实际文件名和位置只记在爸爸本机。 说清 Word 提供需要忠实保留的技术内容。模板现在尚未选定，第 3 讲再从 Overleaf 模板库比较、选择和改造；今天不把某一份模板写成已确定输入。", "url": "topics/word-to-latex/01-project-goal.html#step-1", "status": "active"}, {"topic": "word-to-latex", "topicName": "把技术文档做成书", "audience": "dad", "audienceName": "爸爸", "number": 1, "title": "说清 Word 转 LaTeX 的目标", "step": "2. 写下产出和学习目标", "text": "我们已经选定第一份项目：把一份一百多页的中文 Word 技术文档忠实转换成 LaTeX。排版模板将在第 3 讲由爸爸从 Overleaf 选定，再改造成可复用的中文多章节模板。今天先把已确定的输入、预期产出和学习目标写成一页项目说明；公开课稿只用占位名称。 请爸爸用自己的话确认下表，再在本机写成一页项目说明。 要确认的事 本项目已经确定的方向 已确定的输入 一百多页的中文 Word 原件 待选的排版起点 第 3 讲和爸爸一起选定的 Overleaf 书籍模板 产出 可编译、便于以后修改的 LaTeX 源文件和排版更精美的中文 PDF 内容要求 保留原稿的正文、技术结论、参数、单位、公式和表格数据；改善模板与格式，文字修改另行确认 学习目标 借这份文档学习如何让 AI 按项目目标、文件规则和验证办法持续工作，并把有效做法留给下一份文档复用 前几节已经试过直接写提示词让 AI 完成一次任务。接下来会用同一个文档项目练习更有结构的做法：第 2 讲练中文 LaTeX 编译与 PDF 批注，第 3 讲选并制作中文多章节模板，第 4 讲建立长期项目目录，第 5 讲写项目入口、路线和规则，第 6 讲转换 Word 的一小段并核对、记录可复用的方法。具体字体、图表样式和读者使用场景，以爸爸确认的版本记在项目说明里，尚未决定的标「待定」。 完成时，爸爸能找回 Word 输入，在一页项目说明里写清预期的 LaTeX 源文件、中文 PDF 和工作流学习目标，并说明模板将在第 3 讲一起选定。", "url": "topics/word-to-latex/01-project-goal.html#step-2", "status": "active"}, {"topic": "word-to-latex", "topicName": "把技术文档做成书", "audience": "dad", "audienceName": "爸爸", "number": 2, "title": "编译中文 LaTeX，练习 PDF 批注", "step": "1. 打开练习副本", "text": "这节使用虚构的两章中文 LaTeX 手册。目标是走通「打开项目、编译、定位批注、修改源文件、重新编译、核对 PDF」，再把方法带到自己的技术文档项目。 下载 中文手册练习项目（ZIP） ，在 Finder 解压到「文稿」。保留 ZIP 原件，只在解压后的 chinese-manual 副本里操作。 在 DeepSeek Harness 打开整个练习文件夹，确认工作区指向解压后的副本。 把下面的任务交给 Harness。它应实际执行编译，并报告这次生成文件的位置。 当前工作区是我刚解压的中文 LaTeX 练习副本。请先查看 main.tex 和 chapters/，找出编译入口与两章的引用关系。 使用本机已有的 MacTeX 和 XeLaTeX 编译主文件，并运行足够次数更新目录。请实际执行，报告本次生成的 PDF 路径和编译结果。 如果失败，先指出日志里第一条关键错误和涉及的文件，只在这个练习副本中做必要修复，再重试。需要安装软件或修改系统设置时先告诉我。 我会打开本次生成的 PDF，核对封面、目录和两个中文章节。 编译完成后，打开 Harness 报告的 PDF，核对封面、目录与两个中文章节。看本次编译结果和文件修改时间，避免误看旧 PDF。", "url": "topics/word-to-latex/02-compile-and-annotate.html#step-1", "status": "active"}, {"topic": "word-to-latex", "topicName": "把技术文档做成书", "audience": "dad", "audienceName": "爸爸", "number": 2, "title": "编译中文 LaTeX，练习 PDF 批注", "step": "2. 做一条带位置的批注", "text": "这节使用虚构的两章中文 LaTeX 手册。目标是走通「打开项目、编译、定位批注、修改源文件、重新编译、核对 PDF」，再把方法带到自己的技术文档项目。 在 Harness 预览里确认 dsh-quote-annotate-pro 已启用，选中封面标题，批注「改为『爸爸的技术手册练习』」。 在批注清单确认所选原文正确，把批注发送到当前会话。 发送已选中的批注后，可以在同一会话继续交代任务。 请读取我刚发送的 PDF 划词批注，先告诉我批注选中的原文、对应的 .tex 源文件和准备修改的文字。 等我核对位置后，只改这一处并重新编译主文件。请报告这次生成的 PDF 路径。 我会打开新版 PDF，检查标题已改变，目录和两个中文章节仍可读。 爸爸对照 main.tex 确认 Harness 找到的位置，再让它完成修改和重编。打开新版 PDF，核对新标题、目录和两个章节。若批注插件在本机无法定位，就直接给出 main.tex 与标题原句，按同样的定位和重编步骤完成练习。", "url": "topics/word-to-latex/02-compile-and-annotate.html#step-2", "status": "active"}, {"topic": "word-to-latex", "topicName": "把技术文档做成书", "audience": "dad", "audienceName": "爸爸", "number": 2, "title": "编译中文 LaTeX，练习 PDF 批注", "step": "3. 知道以后去哪里找模板", "text": "这节使用虚构的两章中文 LaTeX 手册。目标是走通「打开项目、编译、定位批注、修改源文件、重新编译、核对 PDF」，再把方法带到自己的技术文档项目。 今天使用的是随课提供的中文 LaTeX 练习文件。下节课会和爸爸一起在 Overleaf 官方模板库 的 Books 分类 选一份喜欢的模板，再用虚构内容把它改成可编译的中文多章节技术书。今天只浏览版式和入口，不必立刻决定选哪一份。 本节以爸爸能在 Harness 预览中选中原文、提交批注，并在重新编译的 PDF 中看到新标题为完成。核对目录和两章仍可读。第 3 讲再选 Overleaf 模板，制作后续课程要用的中文技术书模板。", "url": "topics/word-to-latex/02-compile-and-annotate.html#step-3", "status": "active"}, {"topic": "word-to-latex", "topicName": "把技术文档做成书", "audience": "dad", "audienceName": "爸爸", "number": 3, "title": "做可编译的中文技术书模板", "step": "1. 先看一本书需要什么", "text": "第 2 讲已经编译了两章中文练习，也认识了 Overleaf 模板库。今天不是只给两章加个封面，而是把选中的模板做成 一套可以复制给下一份 Word 文档的中文技术书模板 。 先看两份参考材料： 中文技术书模板（ZIP 源码） 编译结果预览（PDF） 参考模板只用虚构内容，作用是“对照一本书应该有什么”， 不替代 你在 Overleaf 选中的模板。你要做的是把自己的模板补齐；遇到文档类或宏包冲突时，保留功能、换实现方式，不要为了编译通过删章节。 组 一本书里通常要有什么 这一节怎么处理 前置 封面、版权/版本页、前言、目录、图目录、表目录、符号/术语表 先搭骨架，全部放进前言部分 正文 部/章/节、章首页、页眉页脚、页码、脚注、列表、引用块 用中文字体和统一标题层级 图 单图、子图、并排图、图注、正文引用 图片、子图、图注和交叉引用各验一次 表 三线表、定宽表、数值表、横向宽表、跨页长表 数值表用 siunitx ，横向页用 pdflscape 公式/单位 编号公式、多行对齐、SI 数值和单位 公式编号、 \\qty 和单位表各验一次 TikZ 流程图/框图、标注坐标图、时间线或简单 pgfplots 图 图源单独文件，样式统一 代码/提示 代码清单、行号、换行、提示/警告框 listings + tcolorbox 引用/链接 PDF 书签、元数据、图/表/式中文称呼 hyperref + cleveref 后置 附录 A/B、参考文献、索引、术语表 附录和索引都要进目录 交付 模板 README、 latexmkrc 、编译命令、版本/许可、已知问题 写清楚，下一份文档能直接复用 先做骨架，再逐组补功能。每补一组就编译一次；不通过就停在这一组，不继续加下一组。检查表用真实 PDF 结果填，不凭 AI 的一句“已完成”打勾。", "url": "topics/word-to-latex/03-template.html#step-1", "status": "active"}, {"topic": "word-to-latex", "topicName": "把技术文档做成书", "audience": "dad", "audienceName": "爸爸", "number": 3, "title": "做可编译的中文技术书模板", "step": "2. 选模板并保存来源", "text": "第 2 讲已经编译了两章中文练习，也认识了 Overleaf 模板库。今天不是只给两章加个封面，而是把选中的模板做成 一套可以复制给下一份 Word 文档的中文技术书模板 。 先看两份参考材料： 中文技术书模板（ZIP 源码） 编译结果预览（PDF） 参考模板只用虚构内容，作用是“对照一本书应该有什么”， 不替代 你在 Overleaf 选中的模板。你要做的是把自己的模板补齐；遇到文档类或宏包冲突时，保留功能、换实现方式，不要为了编译通过删章节。 打开 Overleaf Books 模板库 ，一起看两三份候选。爸爸先挑喜欢的封面、正文、章节标题和页眉，再核对： 能在 Overleaf 正常编译； 能下载完整源码 ZIP，不是只有 PDF； 文件、宏包和依赖能看懂； 页面说明许可，允许课堂改造； 支持 XeLaTeX/ ctex 或容易改成中文； 结构不太复杂，适合逐步加附录、文献和 TikZ。 在选中的项目里下载源码 ZIP。源码 ZIP 与 PDF 是两次下载，不能把 PDF 当成模板源码。在爸爸本机的私有位置建立 Technical-Publishing/template/original-overleaf/ 和 template/technical-book/ ：前者保存原始 ZIP、来源链接和解压后的只读副本，后者从它复制一套供修改。实际许可和是否允许再发布要看选中模板的页面；本课程不公开选中的源码。", "url": "topics/word-to-latex/03-template.html#step-2", "status": "active"}, {"topic": "word-to-latex", "topicName": "把技术文档做成书", "audience": "dad", "audienceName": "爸爸", "number": 3, "title": "做可编译的中文技术书模板", "step": "3. 搭书骨架", "text": "第 2 讲已经编译了两章中文练习，也认识了 Overleaf 模板库。今天不是只给两章加个封面，而是把选中的模板做成 一套可以复制给下一份 Word 文档的中文技术书模板 。 先看两份参考材料： 中文技术书模板（ZIP 源码） 编译结果预览（PDF） 参考模板只用虚构内容，作用是“对照一本书应该有什么”， 不替代 你在 Overleaf 选中的模板。你要做的是把自己的模板补齐；遇到文档类或宏包冲突时，保留功能、换实现方式，不要为了编译通过删章节。 先把“书的结构”搭出来，不急着补花样。一个可工作的骨架大致是： \\begin{document} \\frontmatter \\input{frontmatter/titlepage} \\input{frontmatter/copyright} \\input{frontmatter/preface} \\tableofcontents \\listoffigures \\listoftables \\input{frontmatter/notation} \\mainmatter \\input{chapters/chapter-01} \\input{chapters/chapter-02} \\appendix \\input{appendix/appendix-a} \\input{appendix/appendix-b} \\backmatter \\printbibliography[title=参考文献] \\printindex \\end{document} 同时补上： 页面：A4、内外边距、装订偏移； 中文字体：正文宋体、标题黑体或宋体、代码等宽； 页码：前言罗马数字，正文阿拉伯数字，附录继续； 章首页、页眉页脚、目录深度； 一张占位封面、版权/版本页、前言、符号/术语表； 两个正文占位章节和一个附录占位章节。 先只让这份骨架编译通过，再补内容。参考模板里的 main.tex 和 frontmatter/ 可以直接对照。", "url": "topics/word-to-latex/03-template.html#step-3", "status": "active"}, {"topic": "word-to-latex", "topicName": "把技术文档做成书", "audience": "dad", "audienceName": "爸爸", "number": 3, "title": "做可编译的中文技术书模板", "step": "4. 补正文版式", "text": "第 2 讲已经编译了两章中文练习，也认识了 Overleaf 模板库。今天不是只给两章加个封面，而是把选中的模板做成 一套可以复制给下一份 Word 文档的中文技术书模板 。 先看两份参考材料： 中文技术书模板（ZIP 源码） 编译结果预览（PDF） 参考模板只用虚构内容，作用是“对照一本书应该有什么”， 不替代 你在 Overleaf 选中的模板。你要做的是把自己的模板补齐；遇到文档类或宏包冲突时，保留功能、换实现方式，不要为了编译通过删章节。 逐项确认： 中文标点、中英文混排、段首缩进和行距； 章/节/小节层级和间距； 脚注、列表、引用块、定理/定义/例； 图注在图下、表注在表上或统一； 页眉显示章名或节名，页码不重复、不跳号。 定理环境可以用 amsthm ： \\newtheorem{definition}{定义}[chapter] \\newtheorem{example}{例}[chapter]", "url": "topics/word-to-latex/03-template.html#step-4", "status": "active"}, {"topic": "word-to-latex", "topicName": "把技术文档做成书", "audience": "dad", "audienceName": "爸爸", "number": 3, "title": "做可编译的中文技术书模板", "step": "5. 补图、表、公式和单位", "text": "第 2 讲已经编译了两章中文练习，也认识了 Overleaf 模板库。今天不是只给两章加个封面，而是把选中的模板做成 一套可以复制给下一份 Word 文档的中文技术书模板 。 先看两份参考材料： 中文技术书模板（ZIP 源码） 编译结果预览（PDF） 参考模板只用虚构内容，作用是“对照一本书应该有什么”， 不替代 你在 Overleaf 选中的模板。你要做的是把自己的模板补齐；遇到文档类或宏包冲突时，保留功能、换实现方式，不要为了编译通过删章节。 这一组最容易“看起来能用、实际不能用”。按下面逐项做： 组别 用什么虚构内容试 打开 PDF 核对什么 单图与子图 一张示意图、两张子图及各自图注 清晰度、子图编号、主图标题、正文引用 三线表 一张带小数的示例表 表头、每格数据、数值对齐 横向宽表 一张列数较多的表 横向页旋转正确，表头可读 跨页长表 一张多页数据表 续页重复表头，不断行失控 公式 一个编号公式、一个多行对齐 编号、对齐、正文引用 SI 单位 12.5 mm 、 23 °C 、 4.2 kW/m² 数字和单位不丢，表格用 S 列对齐 siunitx 示例： \\qty{12.5}{\\milli\\metre} \\qty{23}{\\celsius} \\begin{tabular}{S[table-format=2.1]S[table-format=1.1]} \\toprule {长度 / \\si{\\milli\\metre}} & {温度 / \\si{\\celsius}} \\\\ \\midrule 12.5 & 23.0 \\\\ 8.0 & 22.4 \\\\ \\bottomrule \\end{tabular} 横向页用 pdflscape ，长表用 longtable ；两者的页眉和页码方向要在 PDF 里实际翻看。", "url": "topics/word-to-latex/03-template.html#step-5", "status": "active"}, {"topic": "word-to-latex", "topicName": "把技术文档做成书", "audience": "dad", "audienceName": "爸爸", "number": 3, "title": "做可编译的中文技术书模板", "step": "6. 补 TikZ、代码和提示框", "text": "第 2 讲已经编译了两章中文练习，也认识了 Overleaf 模板库。今天不是只给两章加个封面，而是把选中的模板做成 一套可以复制给下一份 Word 文档的中文技术书模板 。 先看两份参考材料： 中文技术书模板（ZIP 源码） 编译结果预览（PDF） 参考模板只用虚构内容，作用是“对照一本书应该有什么”， 不替代 你在 Overleaf 选中的模板。你要做的是把自己的模板补齐；遇到文档类或宏包冲突时，保留功能、换实现方式，不要为了编译通过删章节。 TikZ 先做一张流程图，再做一张带坐标的标注图。关键是 图源单独文件、样式统一、正文引用一次 ： \\tikzset{ box/.style={draw=teal,fill=teal!8,rounded corners=2pt, minimum width=2.7cm,minimum height=1.1cm,align=center}, arrow/.style={-{Latex[length=2.4mm]},thick,draw=teal} } \\begin{tikzpicture}[node distance=1.1cm and 1.2cm] \\node[box] (a) {采集输入}; \\node[box,right=of a] (b) {检查条件}; \\node[box,right=of b] (c) {执行任务}; \\draw[arrow] (a) -- (b); \\draw[arrow] (b) -- (c); \\end{tikzpicture} 再补： 代码清单： listings ，行号、换行、标题；中文说明放在正文，不塞进代码； 提示/警告框： tcolorbox ，标题写“提示/注意/核对”； 一张 pgfplots 简图或时间线，证明模板能画数据图，不只是方框。 不要在模板里放真实 Word 的代码或技术数据；示例只用虚构内容。", "url": "topics/word-to-latex/03-template.html#step-6", "status": "active"}, {"topic": "word-to-latex", "topicName": "把技术文档做成书", "audience": "dad", "audienceName": "爸爸", "number": 3, "title": "做可编译的中文技术书模板", "step": "7. 补引用、附录和索引", "text": "第 2 讲已经编译了两章中文练习，也认识了 Overleaf 模板库。今天不是只给两章加个封面，而是把选中的模板做成 一套可以复制给下一份 Word 文档的中文技术书模板 。 先看两份参考材料： 中文技术书模板（ZIP 源码） 编译结果预览（PDF） 参考模板只用虚构内容，作用是“对照一本书应该有什么”， 不替代 你在 Overleaf 选中的模板。你要做的是把自己的模板补齐；遇到文档类或宏包冲突时，保留功能、换实现方式，不要为了编译通过删章节。 hyperref ：PDF 书签、标题、作者、链接颜色； cleveref ：中文“图/表/式/章/节”称呼； 参考文献：只选一套方案；参考模板用 biblatex + biber ； 附录： \\appendix 后放附录 A（图示/公式速查）、附录 B（术语/检查表），并让附录进目录； 索引： imakeidx + \\index{} + \\printindex ；至少 10 个词条； 术语表：先用附录表格； glossaries 自动术语表标为选做，避免一次引入太多工具链。 附录骨架： \\appendix \\chapter{图示与公式速查} \\chapter{术语与检查表} 如果本机或 Overleaf 没有自动跑 biber / makeindex ，先记录实际编译命令和报错，不要跳过参考文献或索引却写成“通过”。", "url": "topics/word-to-latex/03-template.html#step-7", "status": "active"}, {"topic": "word-to-latex", "topicName": "把技术文档做成书", "audience": "dad", "audienceName": "爸爸", "number": 3, "title": "做可编译的中文技术书模板", "step": "8. 双处编译、验收和模板交接", "text": "第 2 讲已经编译了两章中文练习，也认识了 Overleaf 模板库。今天不是只给两章加个封面，而是把选中的模板做成 一套可以复制给下一份 Word 文档的中文技术书模板 。 先看两份参考材料： 中文技术书模板（ZIP 源码） 编译结果预览（PDF） 参考模板只用虚构内容，作用是“对照一本书应该有什么”， 不替代 你在 Overleaf 选中的模板。你要做的是把自己的模板补齐；遇到文档类或宏包冲突时，保留功能、换实现方式，不要为了编译通过删章节。 先在本机编译： latexmk -xelatex main.tex 再把 只有虚构内容 的工作副本上传到自己的 Overleaf 项目，用 XeLaTeX 编译一次。两边都通过后，逐项填检查表： 检查项 结果 封面、版权页、前言、目录、图目录、表目录 待核对 前言罗马页码、正文阿拉伯页码、附录继续 待核对 中文标点、字体嵌入、无缺字 待核对 单图、子图、图注、正文引用 待核对 三线表、数值表、横向表、长表 待核对 公式、SI 单位、交叉引用 待核对 TikZ 箭头、标签、打印尺寸 待核对 代码清单、提示框、定理 待核对 参考文献、索引、PDF 书签 待核对 本机与 Overleaf 都能编译 待核对 模板 README、版本、许可、已知问题 待核对 最后给模板写一份 README.md ： 引擎和编译命令； 目录说明； 已包含的功能； 已知限制； 来源和许可； 版本日期。 完成时，爸爸能从 template/technical-book/ 找到主文件、两章、附录、TikZ、表格、代码、README 和最新 PDF；检查表没有未解决的必做项。保留 original-overleaf/ 只读，不把虚构样稿当成 Word 正文。第 4 讲把这份已验证模板放进长期项目目录，并为第一份 Word 单独建立工作区。", "url": "topics/word-to-latex/03-template.html#step-8", "status": "active"}, {"topic": "word-to-latex", "topicName": "把技术文档做成书", "audience": "dad", "audienceName": "爸爸", "number": 4, "title": "分开模板来源、通用模板和项目", "step": "1. 先看完整目标，再建今天要用的部分", "text": "第 3 讲已在本机保存选中的 Overleaf 来源副本和通过检查的中文技术书模板。今天把它们放进长期项目结构，并为第一份 Word 建独立工作区。真实文件、路径和第 3 讲的检查记录留在爸爸本机。 template/technical-book/ 是以后还能复制给第二份文档的通用模板； projects/book-001/latex/ 将是第一份文档自己的模板实例和章节。今天只增加下图标「第 4 讲」的 Word 留存目录；其他文件在对应课次再建立。 Technical-Publishing/ AGENTS.md 第 5 讲：项目入口 ROADMAP.md 第 5 讲：阶段路线 .agents/skills/ word-to-latex/SKILL.md 第 6 讲验证后建立 latex-template-engineering/ 以后维护模板时再建立 technical-writing-review/ 以后独立审校时再建立 standards/ word-conversion.md 第 5 讲：内容保持规则 latex-writing.md 模板版式规则稳定后再建立 template/ original-overleaf/ 第 3 讲：选中模板的来源和只读副本 technical-book/ 第 3 讲：已通过检查的中文通用模板 projects/ book-001/ original/ 第 4 讲：Word 留存副本 latex/ 第 6 讲：模板实例与转换的章节 review/ 第 6 讲：内容核对记录 output/ 第 6 讲：编译出的 PDF book-002/ 第二份文档出现时才创建 development/ 有重要技术决定时再创建 tests/ 第 6 讲：可重复的转换检查 original-overleaf/ 保留下载的原始 ZIP、来源与许可记录，不因后续修改而覆盖。 technical-book/ 是中文模板的工作成果，不放第一份 Word 的私人内容。选中的模板虽在 Overleaf 上可以编辑，真实 Word 仍只在本机项目里处理。", "url": "topics/word-to-latex/04-project-layout.html#step-1", "status": "active"}, {"topic": "word-to-latex", "topicName": "把技术文档做成书", "audience": "dad", "audienceName": "爸爸", "number": 4, "title": "分开模板来源、通用模板和项目", "step": "2. 在 Finder 找回来源、模板和 Word", "text": "第 3 讲已在本机保存选中的 Overleaf 来源副本和通过检查的中文技术书模板。今天把它们放进长期项目结构，并为第一份 Word 建独立工作区。真实文件、路径和第 3 讲的检查记录留在爸爸本机。 关闭窗口后自己重新打开 Technical-Publishing/ ，在 template/original-overleaf/ 找到选中模板的原始 ZIP 与来源记录，在 template/technical-book/ 找到主 .tex 、两章和第 3 讲通过的测试样稿。若第 3 讲的工作副本目前在别处，先把完整文件夹复制到这两个约定位置，保留能恢复的原文件。 回到第 1 讲确认的 Word 原件，试着打开。创建 projects/book-001/original/ ，把整份 Word 复制一份到这里供对照。示例名称是 source-document.docx ；实际文件名保持爸爸自己的，不上传这个仓库，也不覆盖本机原位置。 在本机写一张简短路径表，分别记下原始 Word、项目内 Word 留存副本、Overleaf 来源副本、中文模板主文件和第 3 讲最新 PDF 的实际位置。关掉 Finder 再自己找回一次。", "url": "topics/word-to-latex/04-project-layout.html#step-2", "status": "active"}, {"topic": "word-to-latex", "topicName": "把技术文档做成书", "audience": "dad", "audienceName": "爸爸", "number": 4, "title": "分开模板来源、通用模板和项目", "step": "3. 用只读提示词检查目录", "text": "第 3 讲已在本机保存选中的 Overleaf 来源副本和通过检查的中文技术书模板。今天把它们放进长期项目结构，并为第一份 Word 建独立工作区。真实文件、路径和第 3 讲的检查记录留在爸爸本机。 在 Harness 打开 Technical-Publishing/ 为工作区，发送下面的提示词。今天不开始转换，也不重写模板。 请只读清点当前项目中的 template/original-overleaf/、template/technical-book/ 和 projects/book-001/original/，不要修改、移动、上传或删除任何文件。 报告 Overleaf 来源记录和原始 ZIP 是否在位、中文模板主文件与两个独立章节的相对路径、Word 留存副本的文件名；再指出以后复制模板到 projects/book-001/latex/ 时应保留哪些依赖文件。只报告项目内相对路径，不抄录 Word 正文或私人绝对路径。 我会在 Finder 逐项找回并核对。若实际目录与课稿示例不同，请列为待确认，不要猜测。 爸爸在 Finder 对照 Harness 报告，打开中文模板主文件，确认它没有引用 book-001 。完成时，能说清为什么通用模板、模板来源和第一份文档分别存放；留下一张实际路径表。第 5 讲再写项目入口、阶段路线和内容保持规则。", "url": "topics/word-to-latex/04-project-layout.html#step-3", "status": "active"}, {"topic": "word-to-latex", "topicName": "把技术文档做成书", "audience": "dad", "audienceName": "爸爸", "number": 5, "title": "写项目入口、路线和内容规则", "step": "1. 先分清六种记录", "text": "第 4 讲已把选中的 Overleaf 中文模板与第一份 Word 分开放好。今天只写眼前会用到的三份 Markdown：项目入口 AGENTS.md 、阶段路线 ROADMAP.md 、内容保持规则 standards/word-conversion.md 。Markdown 可以用普通文本编辑器打开， # 表示标题， - 表示一条清单。 名称 回答什么问题 本节怎样处理 AGENTS.md Harness 在这个项目先读什么、可改哪里、怎样汇报？ 放在 Technical-Publishing/ 根目录，写长期边界和文件索引 ROADMAP.md 现在在哪一阶段，下一小步是什么？ 写已验证的模板、首段转换、后续批量转换的顺序 Standard 已确认的内容或排版要求是什么？ 先写 standards/word-conversion.md 中少量确定规则 Development 曾遇到什么重要问题，为什么采用某种解决办法？ 等第 6 讲有真实决定再建，避免预填假经验 Skill 下次同类任务按什么步骤重复？ 第 6 讲验证完一次转换后再写 Tests 怎样检查改动没有破坏已能工作的部分？ 第 6 讲从实际编译和核对中写出 一句话记：入口管边界，路线管阶段，Standard 管要求，Skill 管步骤，Tests 管验证，Development 管决定的原因。 CLAUDE.md 也是部分工具和 Harness 配置可读取的项目指令候选文件；本项目先用一份 AGENTS.md ，不复制一套相同内容。以爸爸本机新会话读到的文件为准。 Harness 项目指令说明", "url": "topics/word-to-latex/05-project-rules.html#step-1", "status": "active"}, {"topic": "word-to-latex", "topicName": "把技术文档做成书", "audience": "dad", "audienceName": "爸爸", "number": 5, "title": "写项目入口、路线和内容规则", "step": "2. 让 Harness 起草，爸爸确认后写入", "text": "第 4 讲已把选中的 Overleaf 中文模板与第一份 Word 分开放好。今天只写眼前会用到的三份 Markdown：项目入口 AGENTS.md 、阶段路线 ROADMAP.md 、内容保持规则 standards/word-conversion.md 。Markdown 可以用普通文本编辑器打开， # 表示标题， - 表示一条清单。 先打开第 1 讲保存在本机的一页项目说明。让 Harness 读取它和第 4 讲的目录， 只在会话里提出草稿 ，不要立即写入文件。 当前工作区是 Technical-Publishing/。请先读取我本机第 1 讲留下的项目说明，再只读查看 template/ 和 projects/book-001/ 的目录。找不到项目说明时先问我位置，不要猜测内容。 请在会话中起草根目录 AGENTS.md、ROADMAP.md 和 standards/word-conversion.md，暂时不要创建或修改文件。 AGENTS.md 写清先读哪些现有文件、只修改 template/technical-book/ 与 projects/book-001/latex/ 等工作副本、原件和留存副本不得覆盖，以及每轮先报告计划和结束时报告核对结果。 ROADMAP.md 区分当前已验证的 Overleaf 中文模板、下一步的 Word 小段转换、以后分批转换与复用。Standard 只写已经确定的内容保持规则；未确定的排版细节标待定。 请逐份列出拟写内容和依据，等我对照项目说明与 Finder 确认。 爸爸逐条核对草稿：目录名是否真存在，Word 的技术内容是否被当作输入，已经验证的通用模板和项目实例的范围是否写对，是否把未决定的字体或图表样式误写成规则。确认后，在 Harness 中说「按刚确认的三份草稿写入对应路径，只创建需要的 standards/ 目录，不动其他文件」；再从 Finder 打开三份文件核对。若 Harness 无法写入，爸爸也可以把确认后的文字粘贴到本机文本编辑器保存。 三份文件可以从下面的 公开示例 起步，实际内容应按爸爸本机项目说明和目录修改。 # AGENTS.md｜项目入口 先读 ROADMAP.md；转换前再读 standards/word-conversion.md。 原件与 template/original-overleaf/、projects/book-001/original/ 只用于读取和核对，不覆盖。 本轮可从 template/technical-book/ 复制模板实例到 projects/book-001/latex/；通用模板不放私人正文。 动手前列出将读、将改的文件及检查办法；完成后报告结果和未解决问题。 # ROADMAP.md｜阶段路线 目标：忠实转换 Word，形成可长期复用的", "url": "topics/word-to-latex/05-project-rules.html#step-2", "status": "active"}, {"topic": "word-to-latex", "topicName": "把技术文档做成书", "audience": "dad", "audienceName": "爸爸", "number": 5, "title": "写项目入口、路线和内容规则", "step": "3. 开新会话验证它读到了什么", "text": "第 4 讲已把选中的 Overleaf 中文模板与第一份 Word 分开放好。今天只写眼前会用到的三份 Markdown：项目入口 AGENTS.md 、阶段路线 ROADMAP.md 、内容保持规则 standards/word-conversion.md 。Markdown 可以用普通文本编辑器打开， # 表示标题， - 表示一条清单。 关闭当前会话，从项目根目录打开 Harness 新会话，发送只读提示词： 请先读当前项目根目录的 AGENTS.md、它指向的 ROADMAP.md，以及 standards/word-conversion.md。暂时不要修改文件或开始转换。 请用自己的话列出当前阶段、下一小步、可以修改的工作副本、不能覆盖的原件，并给出你实际读取的相对路径。找不到文件就报告，不要按记忆补写。 我会打开这三份 Markdown 和 Finder 目录逐项对照，再决定下一步。 爸爸逐项对照三个文件和 Finder。若它没有读到，先确认 Harness 工作区是不是 Technical-Publishing/ ，再明确提供文件路径重试，并记下本机的加载情况。完成时，新会话能说对项目阶段和原件边界，爸爸能指出以后该把步骤、检查和重要决定分别放在哪里。", "url": "topics/word-to-latex/05-project-rules.html#step-3", "status": "active"}, {"topic": "word-to-latex", "topicName": "把技术文档做成书", "audience": "dad", "audienceName": "爸爸", "number": 6, "title": "转换一小段 Word 并沉淀流程", "step": "1. 定位输入，先只做计划", "text": "第 3 讲已选好并验证 Overleaf 中文模板，第 4 讲建了项目目录，第 5 讲写了入口、路线和内容规则。今天从本机 Word 选一个小节，按「计划 → 执行 → 编译与核对 → 沉淀」走完第一轮。模板已能编译中文；这一节专注于忠实转换这段内容，后续再扩大范围。 在 projects/book-001/original/ 的 Word 留存副本里，选一个有标题、正文和数字或单位的小节。在本机记下标题与页码或段落位置，不把原文粘到公开课程仓库。建立 projects/book-001/latex/ 、 review/ 、 output/ 。若 Harness 无法读取 Word 正文，爸爸在私人会话里提供这一小节的文字或本机工作副本，要求它说明实际读到了什么。 当前工作区是 Technical-Publishing/。请先读 AGENTS.md、ROADMAP.md、standards/word-conversion.md，再只读查看 projects/book-001/original/ 中我指定的 Word 小节，以及 template/technical-book/。若不能读取 Word，请停下并告诉我需要我提供哪一段。 这一轮只处理我指定的一个小节。请先给计划，不创建或修改文件：列出原文标题和位置、怎样把第 3 讲验证的通用模板复制成 projects/book-001/latex/ 中的项目实例、拟生成的章节文件、编译入口，以及 Word、LaTeX、PDF 三处要核对的项目。 不要改原件或留存副本，不要润色技术文字；遇到表格、公式、图和原稿编号，说明会怎样保留与核对。等我确认计划后再执行。 爸爸对照 Word 原文和 Finder 核对计划中的小节边界、目标路径、原件保护和检查办法。计划扩大到整章、擅自改字句或凭猜测描述未读到的材料时，先让 Harness 改正计划。", "url": "topics/word-to-latex/06-convert-segment.html#step-1", "status": "followup"}, {"topic": "word-to-latex", "topicName": "把技术文档做成书", "audience": "dad", "audienceName": "爸爸", "number": 6, "title": "转换一小段 Word 并沉淀流程", "step": "2. 按确认的范围转换并编译", "text": "第 3 讲已选好并验证 Overleaf 中文模板，第 4 讲建了项目目录，第 5 讲写了入口、路线和内容规则。今天从本机 Word 选一个小节，按「计划 → 执行 → 编译与核对 → 沉淀」走完第一轮。模板已能编译中文；这一节专注于忠实转换这段内容，后续再扩大范围。 计划确认后，才发送执行提示词。 template/original-overleaf/ 和 projects/book-001/original/ 始终只读； template/technical-book/ 保持第 3 讲通过检查的通用版本。把完整模板复制到 projects/book-001/latex/ 作为本书实例，只在实例中加入真实章节，避免通用模板引用 book-001 的私人内容。 按我刚确认的计划，只转换指定的 Word 小节。先把 template/technical-book/ 中已验证的模板完整复制为 projects/book-001/latex/ 的项目实例，在实例中写入本段 .tex 章节并接入主文件。保持原文正文、数字、单位、公式、表格数据和技术结论，不自行润色、补写或重绘技术关系。 只改 projects/book-001/latex/。不要改 template/original-overleaf/、template/technical-book/ 或 Word 留存副本。若实际材料出现第 3 讲模板未测试过的结构，先报告缺口和建议，不要擅自扩张模板。 请实际编译项目实例，报告改动文件、编译方式、最新 PDF 路径、第一条关键错误和未解决问题。编译成功后把本次 PDF 放入 projects/book-001/output/。我会打开 Word、.tex 和 PDF 核对，再决定是否沉淀流程。 爸爸打开新 PDF，核对文件时间和显示的内容，避免误看旧版本。若本段有新的模板需求，先记录并回到模板工作副本单独验证，再重新复制到项目实例；没有编译成功和内容核对结果时，本节仍在进行中。", "url": "topics/word-to-latex/06-convert-segment.html#step-2", "status": "followup"}, {"topic": "word-to-latex", "topicName": "把技术文档做成书", "audience": "dad", "audienceName": "爸爸", "number": 6, "title": "转换一小段 Word 并沉淀流程", "step": "3. 做有证据的人工核对", "text": "第 3 讲已选好并验证 Overleaf 中文模板，第 4 讲建了项目目录，第 5 讲写了入口、路线和内容规则。今天从本机 Word 选一个小节，按「计划 → 执行 → 编译与核对 → 沉淀」走完第一轮。模板已能编译中文；这一节专注于忠实转换这段内容，后续再扩大范围。 在本机建立 projects/book-001/review/segment-001.md ，逐项记 Word 的位置、对应 .tex 文件、PDF 页码、核对结果和待处理问题。由爸爸亲自对照三处，不让 AI 只凭自己的转换稿给自己打勾。 核对什么 怎样对照 标题、段落与顺序 从 Word 原段逐段找到 .tex 和 PDF 中的对应内容 数字、单位、公式、技术结论 按原文逐项核对，不把格式改善当成内容改写 表格 核对每行每列的数据；允许版式变化，不漏项 图与技术连接关系 保留原图供核对；以后要重绘，先确认连接和参数没有变化 编号与交叉引用 记录 Word 编号到 LaTeX 标签、PDF 显示的对应关系 项目编译 打开本次 PDF，检查中文、目录或引用及未修改部分仍可读 小节没有的项目写「不适用」，没核对到的写「待核对」，不要填成通过。内容措辞若需要润色，另列建议请爸爸确认，不混入这次格式转换。", "url": "topics/word-to-latex/06-convert-segment.html#step-3", "status": "followup"}, {"topic": "word-to-latex", "topicName": "把技术文档做成书", "audience": "dad", "audienceName": "爸爸", "number": 6, "title": "转换一小段 Word 并沉淀流程", "step": "4. 把验证过的做法留下来", "text": "第 3 讲已选好并验证 Overleaf 中文模板，第 4 讲建了项目目录，第 5 讲写了入口、路线和内容规则。今天从本机 Word 选一个小节，按「计划 → 执行 → 编译与核对 → 沉淀」走完第一轮。模板已能编译中文；这一节专注于忠实转换这段内容，后续再扩大范围。 先区分本轮产生的四种记录。 review/segment-001.md 保存这份文档的核对证据； tests/word-segment-check.md 写能重复执行的转换与编译检查，包括入口、实际运行方式、预期现象与本轮结果； development/decisions.md 仅在确实解决了转换或引用问题时记录「问题、原因、采用的改法、验证结果」。经核对的通用内容要求继续放 standards/word-conversion.md 。具体 .tex 的改动历史将来交给 Git，Development 负责解释重要决定的原因。 两份检查记录可以先照下面的占位格式写，填写时只用爸爸本机的真实结果： # projects/book-001/review/segment-001.md Word 位置：本机第［页／节］；LaTeX 文件：［相对路径］；PDF：［文件及页码］ 标题与段落：待核对；数字与单位：待核对 表格／图／公式／引用：按本段实际内容填写通过、不适用或待核对 未解决问题：［实际问题或“无”］ # tests/word-segment-check.md 编译入口：［本次使用的 book-001 项目实例主文件］ 重复办法：［Harness 实际执行的编译命令或操作］ 预期：生成新 PDF，本段标题与内容可读，目录或引用按本段实际情况显示 本次结果：［运行时间、PDF 位置、通过或实际错误］ 本轮通过后，再请 Harness 起草第一份可复用 Skill： 请先读本轮的 Word 小节、转换后的 .tex、最新 PDF、projects/book-001/review/segment-001.md 和 tests/word-segment-check.md。只根据实际通过的检查，起草 .agents/skills/word-to-latex/SKILL.md；先在会话中展示草稿，等我确认后再写入。 Skill 只记录下次转换另一小节时可重复的步骤：定位原文、规划对应文件、只改工作副本、编译、对照原文和记录待确认项。规则请引用 standards/word-conversion.md，不要复制一大段；未经验证的修复不要写成固定步骤。 同时建议 ROADMAP.md 的下一小步。若产生了稳定新规则或实际技术决定，指出应更新哪份文件及依据；没有变化的文件保持不动。我会对照本轮核对记录确认。 下面只示范 Skill 的最小形状，爸爸应以本轮确实验证过的步骤写自己的版本。 Harness 项目 Sk", "url": "topics/word-to-latex/06-convert-segment.html#step-4", "status": "followup"}, {"topic": "cad", "topicName": "和图纸对话", "audience": "dad", "audienceName": "爸爸", "number": 0, "title": "和图纸对话", "step": "专题介绍", "text": "AutoCAD 工艺流程图：精确读取与修改 把 DWG 变成可读的 DXF，建立覆盖报告，用计划式修改精确改图并自动校验。 ", "url": "topics/cad/index.html", "status": "active"}, {"topic": "cad", "topicName": "和图纸对话", "audience": "dad", "audienceName": "爸爸", "number": 1, "title": "把 DWG 变成可精确读取的 DXF", "step": "1. 建一个只放工作副本的私有目录", "text": "这一讲开始，所有自动化都在 文件 上做：读取 DXF 里的图层、块、实体、属性和 handle，不向 AutoCAD 窗口键入任何命令。AutoCAD 只负责你自己打开、查看和核对。 先明确一件事：我们不是让 AI「看图猜」，而是让它读到图纸的矢量数据。第一步就是把 DWG 变成 DXF。 在 Finder 的「文稿」里新建 CAD-Review/ ，真实图纸和所有产出都留在这里，不进课程仓库。 CAD-Review/ ├── original/ AutoCAD 原件，只读，不覆盖 ├── dxf/ 另存或转换出来的 DXF ├── toolkit/ 本课下载的工具箱 ├── inventory/ 结构化清单 ├── work/ 修改后的副本 ├── review/ 审图页与批注 └── notes/ 每张图的核对记录 也可以在 Harness 里说「当前工作区是 CAD-Review/，只创建 original、dxf、toolkit、inventory、work、review、notes 七个空目录，不要复制或移动现有文件」。", "url": "topics/cad/01-convert-to-dxf.html#step-1", "status": "active"}, {"topic": "cad", "topicName": "和图纸对话", "audience": "dad", "audienceName": "爸爸", "number": 1, "title": "把 DWG 变成可精确读取的 DXF", "step": "2. 在 AutoCAD 里另存为 DXF（主路线）", "text": "这一讲开始，所有自动化都在 文件 上做：读取 DXF 里的图层、块、实体、属性和 handle，不向 AutoCAD 窗口键入任何命令。AutoCAD 只负责你自己打开、查看和核对。 先明确一件事：我们不是让 AI「看图猜」，而是让它读到图纸的矢量数据。第一步就是把 DWG 变成 DXF。 在 AutoCAD 打开要整理的图纸，先记下图号、图名和版本。 选「文件 → 另存为」，文件类型选 AutoCAD 2018 DXF (*.dxf) ，存到 CAD-Review/dxf/ 。菜单名称以你本机版本为准；命令行 DXFOUT 也可以。 文件名用图号，例如 DEMO-PFD-001.dxf ，后面的清单、计划、审图页都用同一个名字。 图纸引用了外部参照（XREF）时，先在 AutoCAD 里用 XREF 面板绑定再另存；未绑定的参照不会进入 DXF。 确认原件没有被覆盖。同目录里多出来的 .bak 或 .dxf 只是副本。", "url": "topics/cad/01-convert-to-dxf.html#step-2", "status": "active"}, {"topic": "cad", "topicName": "和图纸对话", "audience": "dad", "audienceName": "爸爸", "number": 1, "title": "把 DWG 变成可精确读取的 DXF", "step": "3. 批量转换（可选）", "text": "这一讲开始，所有自动化都在 文件 上做：读取 DXF 里的图层、块、实体、属性和 handle，不向 AutoCAD 窗口键入任何命令。AutoCAD 只负责你自己打开、查看和核对。 先明确一件事：我们不是让 AI「看图猜」，而是让它读到图纸的矢量数据。第一步就是把 DWG 变成 DXF。 图纸很多时，可以让程序批量转换，但需要先装 ODA File Converter （官方免费，选 macOS 13 以上、Apple 芯片版）。装好后： python3 toolkit/cad.py convert original/ -o dxf/ --to dxf 没有安装时，命令会打印手动步骤，不会假装转换成功。Homebrew 的 libredwg （ dwg2dxf ）只作最后手段，结果必须逐张核对。", "url": "topics/cad/01-convert-to-dxf.html#step-3", "status": "active"}, {"topic": "cad", "topicName": "和图纸对话", "audience": "dad", "audienceName": "爸爸", "number": 1, "title": "把 DWG 变成可精确读取的 DXF", "step": "4. 准备工具箱环境", "text": "这一讲开始，所有自动化都在 文件 上做：读取 DXF 里的图层、块、实体、属性和 handle，不向 AutoCAD 窗口键入任何命令。AutoCAD 只负责你自己打开、查看和核对。 先明确一件事：我们不是让 AI「看图猜」，而是让它读到图纸的矢量数据。第一步就是把 DWG 变成 DXF。 下载工具箱： cad.py 、 cad_inventory.py 、 cad_edit.py 、 make_review_sheet.py 、 requirements.txt ，放进 CAD-Review/toolkit/ 。 在 CAD-Review/ 里建独立环境： python3 -m venv .venv-cad .venv-cad/bin/python -m pip install -r toolkit/requirements.txt 先跑一次自检，确认读、改、校验三条链路都正常： .venv-cad/bin/python toolkit/cad.py selftest 自检会在一张虚构示例上跑完整流程，最后输出「自检全部通过」。任何一项失败，先修环境或把报错记进 notes/ ，不要继续。", "url": "topics/cad/01-convert-to-dxf.html#step-4", "status": "active"}, {"topic": "cad", "topicName": "和图纸对话", "audience": "dad", "audienceName": "爸爸", "number": 1, "title": "把 DWG 变成可精确读取的 DXF", "step": "5. 生成第一份清单", "text": "这一讲开始，所有自动化都在 文件 上做：读取 DXF 里的图层、块、实体、属性和 handle，不向 AutoCAD 窗口键入任何命令。AutoCAD 只负责你自己打开、查看和核对。 先明确一件事：我们不是让 AI「看图猜」，而是让它读到图纸的矢量数据。第一步就是把 DWG 变成 DXF。 先拿虚构示例练手，再换成自己的图。示例可以下载： sample-pfd.dxf 。 .venv-cad/bin/python toolkit/cad.py inventory dxf/DEMO-PFD-001.dxf -o inventory 打开 inventory/DEMO-PFD-001.md ，再打开同名 .json 。先看四件事： 先看什么 在哪里 文件 sha256、DXF 版本、编码、审计结果 .json 开头与 .md 顶部 图层表：每层实体数、零实体图层 .md 的图层表 块：定义、引用次数、属性标签 .md / .json 的 blocks 、 block_attrib_tags 异常：外部参照、代理对象、缺失字体、空图层 warnings", "url": "topics/cad/01-convert-to-dxf.html#step-5", "status": "active"}, {"topic": "cad", "topicName": "和图纸对话", "audience": "dad", "audienceName": "爸爸", "number": 1, "title": "把 DWG 变成可精确读取的 DXF", "step": "6. 只读清单，让 Harness 复述事实", "text": "这一讲开始，所有自动化都在 文件 上做：读取 DXF 里的图层、块、实体、属性和 handle，不向 AutoCAD 窗口键入任何命令。AutoCAD 只负责你自己打开、查看和核对。 先明确一件事：我们不是让 AI「看图猜」，而是让它读到图纸的矢量数据。第一步就是把 DWG 变成 DXF。 当前工作区是 CAD-Review/。请只读 inventory/ 里的清单文件，先报告你实际打开了哪几个文件。 然后只根据文件内容回答： 1. 图框里的图名、图号、版本、日期； 2. 图层表里每层的实体数，哪些图层没有实体； 3. 设备位号与名称、仪表位号与名称； 4. 位号候选里哪些像管线号、哪些像设备或仪表位号； 5. warnings 里有哪些异常，各自影响什么。 每条结论注明来自哪条文字或哪个 handle。文件里没有的写「无法从文件确认」，不要补猜，也不要评价工艺。", "url": "topics/cad/01-convert-to-dxf.html#step-6", "status": "active"}, {"topic": "cad", "topicName": "和图纸对话", "audience": "dad", "audienceName": "爸爸", "number": 1, "title": "把 DWG 变成可精确读取的 DXF", "step": "7. 亲手核对", "text": "这一讲开始，所有自动化都在 文件 上做：读取 DXF 里的图层、块、实体、属性和 handle，不向 AutoCAD 窗口键入任何命令。AutoCAD 只负责你自己打开、查看和核对。 先明确一件事：我们不是让 AI「看图猜」，而是让它读到图纸的矢量数据。第一步就是把 DWG 变成 DXF。 打开 AutoCAD 原图，对照清单： 核对什么 清单里怎么写 原图里怎么看 图名、图号 标题栏文字与 handle 打开图框逐字对照 图层数量 图层表的行数 图层管理器里的图层数 某层实体数 该图层行的实体数 关闭其他图层，数该层图元 设备/仪表位号 设备、仪表清单的 TAG 与 handle 在图上找到该位号 核对结果写进 notes/<图号>-阅读.md ：这张图能不能完整读出、哪些内容没读到、编码和外部参照有没有问题。", "url": "topics/cad/01-convert-to-dxf.html#step-7", "status": "active"}, {"topic": "cad", "topicName": "和图纸对话", "audience": "dad", "audienceName": "爸爸", "number": 1, "title": "把 DWG 变成可精确读取的 DXF", "step": "检查清单", "text": "这一讲开始，所有自动化都在 文件 上做：读取 DXF 里的图层、块、实体、属性和 handle，不向 AutoCAD 窗口键入任何命令。AutoCAD 只负责你自己打开、查看和核对。 先明确一件事：我们不是让 AI「看图猜」，而是让它读到图纸的矢量数据。第一步就是把 DWG 变成 DXF。 [ ] CAD-Review/ 七个目录已建好，原件只读。 [ ] 至少一张图另存为 AutoCAD 2018 DXF，文件名用图号。 [ ] 外部参照已绑定，或已在笔记里记录未绑定情况。 [ ] .venv-cad 可用， cad.py selftest 全部通过。 [ ] 生成了 inventory/<图号>.json 与 .md ，warnings 逐条看过。 [ ] Harness 的复述能指回 handle，没有补猜。 [ ] 至少核对了图名、图层数和两个位号。 下一讲： 精确读懂一张图 。 备查： ODA File Converter · ezdxf 文档 · 工具箱说明", "url": "topics/cad/01-convert-to-dxf.html#step-8", "status": "active"}, {"topic": "cad", "topicName": "和图纸对话", "audience": "dad", "audienceName": "爸爸", "number": 2, "title": "精确读懂一张图", "step": "1. 先看覆盖报告", "text": "上一讲生成了第一份清单。这一讲不急着改图，先把「读得准」这件事做扎实：清单里的每个结论都要能指回文件里的某个 handle，覆盖报告里没有读到的部分要明确说出来。 打开 inventory/<图号>.json ，看 coverage ： 字段 含义 为什么要看 layers / layers_with_entities 图层总数与有实体的图层数 两者差太多，说明有大量空图层或图层表被清理过 block_definitions / block_inserts 块定义数与块引用数 定义多、引用少，可能有未使用块库 entity_types 出现过的实体类型数 类型太少要警惕代理对象或外部参照 xrefs 未绑定的外部参照 不为空说明图纸不完整 proxy_objects 代理对象数 大于 0 说明有 AutoCAD 自定义对象，几何可能读不全 texts 文字条数 与图纸上的文字量做直觉对照 再看 warnings 。每一条要么解释清楚，要么在 notes/ 里记下「为什么暂时不影响」。", "url": "topics/cad/02-read-a-drawing.html#step-1", "status": "active"}, {"topic": "cad", "topicName": "和图纸对话", "audience": "dad", "audienceName": "爸爸", "number": 2, "title": "精确读懂一张图", "step": "2. 图层：清单 vs 图层管理器", "text": "上一讲生成了第一份清单。这一讲不急着改图，先把「读得准」这件事做扎实：清单里的每个结论都要能指回文件里的某个 handle，覆盖报告里没有读到的部分要明确说出来。 在 AutoCAD 打开原图，打开图层管理器，记下图层总数。 对照清单里的图层表：逐一核对名称、颜色、线型、开/关、冻结、锁定。 找一两个实体较多的图层，关闭其他图层，数一遍图元，和清单里的实体数对照。 如果清单里有原图没有的图层，或原图有清单里没有的图层，先查是不是换了版本或打开了别的图。", "url": "topics/cad/02-read-a-drawing.html#step-2", "status": "active"}, {"topic": "cad", "topicName": "和图纸对话", "audience": "dad", "audienceName": "爸爸", "number": 2, "title": "精确读懂一张图", "step": "3. 块、属性与位号", "text": "上一讲生成了第一份清单。这一讲不急着改图，先把「读得准」这件事做扎实：清单里的每个结论都要能指回文件里的某个 handle，覆盖报告里没有读到的部分要明确说出来。 设备与仪表通常以块参照出现，位号在块的属性里。 打开 .md 的设备、仪表清单，每条有 handle、TAG、NAME、块名和插入点。 在 AutoCAD 里选中同一台设备，看属性面板里的 TAG 和 NAME 是否与清单一致。 核对 block_attrib_tags ：每个块的属性标签是否齐全；缺少 NAME 或 TAG 的块要单独记下来。 抽 3 个位号，把 handle 记进笔记。下一讲做跨图核对时，handle 就是证据。", "url": "topics/cad/02-read-a-drawing.html#step-3", "status": "active"}, {"topic": "cad", "topicName": "和图纸对话", "audience": "dad", "audienceName": "爸爸", "number": 2, "title": "精确读懂一张图", "step": "4. 文字与图框", "text": "上一讲生成了第一份清单。这一讲不急着改图，先把「读得准」这件事做扎实：清单里的每个结论都要能指回文件里的某个 handle，覆盖报告里没有读到的部分要明确说出来。 清单里的 texts 保留原始字符串、图层、位置和 handle；中文是 DXF 里的原文，不是渲染图上的字。 title_block 是标为 TITLE 图层的文字；如果你的图框在别的图层，用 --title-layer 重新生成清单： .venv-cad/bin/python toolkit/cad.py inventory dxf/<图号>.dxf -o inventory --title-layer 图框 清单和审图页都支持 --title-layer ；图框不在 TITLE 图层时，先按图层表确认它的图层名再重跑。 图名、图号、版本、日期四项必须和原图逐字一致；有一位不同都要记下来。", "url": "topics/cad/02-read-a-drawing.html#step-4", "status": "active"}, {"topic": "cad", "topicName": "和图纸对话", "audience": "dad", "audienceName": "爸爸", "number": 2, "title": "精确读懂一张图", "step": "5. 让 Harness 做一次「带证据的复述」", "text": "上一讲生成了第一份清单。这一讲不急着改图，先把「读得准」这件事做扎实：清单里的每个结论都要能指回文件里的某个 handle，覆盖报告里没有读到的部分要明确说出来。 当前工作区是 CAD-Review/。请只读 inventory/<图号>.json 和 .md，不要打开或修改 dxf/、original/ 里的图纸。 请按下面的顺序复述，每条都带证据（handle、文字原文或图层名）： 1. 这张图的图名、图号、版本、日期； 2. 图层完整性：图层总数、有实体的图层、零实体图层； 3. 块与属性：每类设备的块名、属性标签是否齐全； 4. 设备、仪表位号清单； 5. 文字里有没有明显的图框信息、说明、管线号； 6. 覆盖报告的缺口：外部参照、代理对象、空图层、编码或字体问题。 不要推断工艺连接，不要补猜缺失位号；文件里没有的写「无法从文件确认」。", "url": "topics/cad/02-read-a-drawing.html#step-5", "status": "active"}, {"topic": "cad", "topicName": "和图纸对话", "audience": "dad", "audienceName": "爸爸", "number": 2, "title": "精确读懂一张图", "step": "6. 写一页「这张图读到了什么」", "text": "上一讲生成了第一份清单。这一讲不急着改图，先把「读得准」这件事做扎实：清单里的每个结论都要能指回文件里的某个 handle，覆盖报告里没有读到的部分要明确说出来。 在 notes/<图号>-阅读.md 记录： # <图号> 阅读记录 - 文件与版本： - 图层：共 __ 层，有实体 __ 层，零实体 __ 层 - 块：定义 __ 个，引用 __ 次；属性缺失：__ - 设备：__ 台；仪表：__ 个 - 图框：图名 __、图号 __、版本 __、日期 __ - 未解决：外部参照 / 代理对象 / 编码 / 字体 / 其他 - 我核对过的 handle：__", "url": "topics/cad/02-read-a-drawing.html#step-6", "status": "active"}, {"topic": "cad", "topicName": "和图纸对话", "audience": "dad", "audienceName": "爸爸", "number": 2, "title": "精确读懂一张图", "step": "检查清单", "text": "上一讲生成了第一份清单。这一讲不急着改图，先把「读得准」这件事做扎实：清单里的每个结论都要能指回文件里的某个 handle，覆盖报告里没有读到的部分要明确说出来。 [ ] 能说清覆盖报告里每个字段的含义。 [ ] 图层总数、有实体图层数与原图对照过。 [ ] 抽 3 个位号，TAG、NAME、handle 与原图一致。 [ ] 图名、图号、版本、日期逐字核对。 [ ] warnings 每条都有处理或记录。 [ ] 写完了 notes/<图号>-阅读.md 。 [ ] 没有把 AI 的推断当成文件事实。 上一讲： 把 DWG 变成可精确读取的 DXF · 下一讲： 批量台账与跨图核对 。 备查： ezdxf 图层与块 · 工具箱说明", "url": "topics/cad/02-read-a-drawing.html#step-7", "status": "active"}, {"topic": "cad", "topicName": "和图纸对话", "audience": "dad", "audienceName": "爸爸", "number": 3, "title": "批量台账与跨图核对", "step": "1. 选一批有关联的图", "text": "单张图读准之后，真正花时间的是「一批图放在一起看」。这一讲不追求一次处理几百张，先把 3–5 张关联图纸的台账和疑点清单跑通。 从同一套装置或同一阶段里选 3–5 张，例如总流程、反应、分离各一张。 每张都按第一讲另存成 DXF，文件名用图号，放进 dxf/ 。 在 notes/ 里各写一行：这张图是什么、和图里哪几张相关、有没有未绑定参照。", "url": "topics/cad/03-batch-and-cross-check.html#step-1", "status": "active"}, {"topic": "cad", "topicName": "和图纸对话", "audience": "dad", "audienceName": "爸爸", "number": 3, "title": "批量台账与跨图核对", "step": "2. 批量生成台账", "text": "单张图读准之后，真正花时间的是「一批图放在一起看」。这一讲不追求一次处理几百张，先把 3–5 张关联图纸的台账和疑点清单跑通。 .venv-cad/bin/python toolkit/cad.py inventory dxf/ -o inventory 每张图生成一份 .md 和 .json ，另外汇总 inventory/ledger.csv 。先看台账： 列 先看什么 file 是否都用图号 dxf_version 是否统一到 AC1032（R2018） entities / texts 明显偏少可能是参照没绑定 equipment / instruments 与印象差太多时先核对 tags 用于发现漏提取 warnings 不为 0 的图先处理 台账不是结论，只是「这批图能不能读、读到了多少」的体检表。", "url": "topics/cad/03-batch-and-cross-check.html#step-2", "status": "active"}, {"topic": "cad", "topicName": "和图纸对话", "audience": "dad", "audienceName": "爸爸", "number": 3, "title": "批量台账与跨图核对", "step": "3. 让 Harness 只列疑点", "text": "单张图读准之后，真正花时间的是「一批图放在一起看」。这一讲不追求一次处理几百张，先把 3–5 张关联图纸的台账和疑点清单跑通。 当前工作区是 CAD-Review/。请只读 inventory/ledger.csv 和这批图的清单（.md 与 .json），不要打开或修改 original/、dxf/ 里的图纸。 请做一次跨图核对，但不要下结论。只列需要我人工确认的项目，分四类： 1. 同一位号在不同图纸里名称、参数或位置不一致； 2. 设备或仪表位号重复、跳号、或只出现在一张图里； 3. 图层命名、图框版本、图号格式不一致； 4. 清单里读不到或可能缺内容的地方（外部参照、代理对象、编码问题）。 每条写清：疑点、证据（文件 + handle + 原文）、为什么值得核对、建议我在原图里看哪里。 没有把握的写「待确认」，不要编造位号，也不要替我判断工艺是否合理。 最后列出你认为我应该先核对的三条，并说明理由。", "url": "topics/cad/03-batch-and-cross-check.html#step-3", "status": "active"}, {"topic": "cad", "topicName": "和图纸对话", "audience": "dad", "audienceName": "爸爸", "number": 3, "title": "批量台账与跨图核对", "step": "4. 逐条判定", "text": "单张图读准之后，真正花时间的是「一批图放在一起看」。这一讲不追求一次处理几百张，先把 3–5 张关联图纸的台账和疑点清单跑通。 在 notes/cross-check-<日期>.md 里逐条判定： 判定 什么情况用 记录要写什么 成立 原图确实如此 图号、handle、原图位置、你的判断 不成立 清单提取或 AI 理解有误 错在哪：文字、块、图层还是推断 需原件确认 本机副本看不清或版本不对 缺什么、去找哪份原件 没核对到的写「待核对」，不填「通过」。", "url": "topics/cad/03-batch-and-cross-check.html#step-4", "status": "active"}, {"topic": "cad", "topicName": "和图纸对话", "audience": "dad", "audienceName": "爸爸", "number": 3, "title": "批量台账与跨图核对", "step": "5. 把规则留下来", "text": "单张图读准之后，真正花时间的是「一批图放在一起看」。这一讲不追求一次处理几百张，先把 3–5 张关联图纸的台账和疑点清单跑通。 跑完两三批图后，只写已经确认的规则到 standards/cad-review.md ： # standards/cad-review.md｜图纸核对规则 - 位号格式：设备用「字母-三位数字」，仪表用「两位功能字母 + 编号」；以本装置现有图纸为准。 - 图号与文件名一致；另存 DXF 统一用 AutoCAD 2018 DXF。 - 先绑定外部参照再另存；有未绑定参照的图不进入跨图核对。 - 文字编码：R2004 及以前用 $DWGCODEPAGE，出现乱码先用 ODA 重出 ACAD2018。 - inventory warnings 不为 0 的图先处理，不进入下一步。 - AI 只能提出疑点；每条结论必须能指回「文件 + handle + 原文」。 不确定的标「待定」，不要写成制度。", "url": "topics/cad/03-batch-and-cross-check.html#step-5", "status": "active"}, {"topic": "cad", "topicName": "和图纸对话", "audience": "dad", "audienceName": "爸爸", "number": 3, "title": "批量台账与跨图核对", "step": "检查清单", "text": "单张图读准之后，真正花时间的是「一批图放在一起看」。这一讲不追求一次处理几百张，先把 3–5 张关联图纸的台账和疑点清单跑通。 [ ] 这一批 3–5 张图都按图号命名并另存为 DXF。 [ ] ledger.csv 已生成，每张图一行。 [ ] warnings 不为 0 的图已处理或已记录原因。 [ ] 跨图结果只包含「疑点 + 证据 + 建议核对位置」。 [ ] 每条疑点都有成立/不成立/需原件确认的判定。 [ ] standards/cad-review.md 只写已确认规则。 上一讲： 精确读懂一张图 · 下一讲： 审图页与批注 。 备查： 工具箱说明 · ezdxf 文档", "url": "topics/cad/03-batch-and-cross-check.html#step-6", "status": "active"}, {"topic": "cad", "topicName": "和图纸对话", "audience": "dad", "audienceName": "爸爸", "number": 4, "title": "审图页与批注讨论", "step": "1. 生成审图页", "text": "清单适合查数，不适合「看着图说话」。这一讲把一张图变成可缩放、按图层显示、点选实体、写批注的审图页；批注和实体 handle 绑定，讨论时不会脱离图纸。 .venv-cad/bin/python toolkit/cad.py review dxf/<图号>.dxf -o review/<图号>.html \\ --title \"<图名>\" 几何用矢量 SVG 逐图层渲染，放大不糊；中文文字单独叠加，不依赖 AutoCAD 的 SHX 字体。 设备、仪表和标题栏文字都有编号热点，热点带 handle，能对回 DXF 实体。 单文件、无外部依赖，可以离线打开。 示例可以看： sample-review.html 。", "url": "topics/cad/04-review-and-annotate.html#step-1", "status": "active"}, {"topic": "cad", "topicName": "和图纸对话", "audience": "dad", "audienceName": "爸爸", "number": 4, "title": "审图页与批注讨论", "step": "2. 打开与操作", "text": "清单适合查数，不适合「看着图说话」。这一讲把一张图变成可缩放、按图层显示、点选实体、写批注的审图页；批注和实体 handle 绑定，讨论时不会脱离图纸。 在 Harness 右侧 Files 面板打开 review/<图号>.html ；也可以用浏览器打开同一文件。 用「放大 / 缩小 / 适应窗口」和拖动查看细节。 勾选左侧图层，只看设备、仪表或管线。 点编号热点，看位号、名称、图层、块名和 handle。 在文本框写批注，点「保存批注」。批注存在本机浏览器里，可「导出批注 JSON」或「复制批注」。 Harness 预览是受限沙箱页面，页面自带的批注可能存不住、下载也可能被拦；要长期保存就在浏览器里打开同一份 HTML。「和 AI 一起做事」第 2 讲装过 HTML 批注插件（Installed plugins 里显示为 HTML Annotations 或 dsh-annotate-sync ）时，也可以在预览里用「点选批注」浮层，以本机实际显示为准。", "url": "topics/cad/04-review-and-annotate.html#step-2", "status": "active"}, {"topic": "cad", "topicName": "和图纸对话", "audience": "dad", "audienceName": "爸爸", "number": 4, "title": "审图页与批注讨论", "step": "3. 批注要挂在实体上", "text": "清单适合查数，不适合「看着图说话」。这一讲把一张图变成可缩放、按图层显示、点选实体、写批注的审图页；批注和实体 handle 绑定，讨论时不会脱离图纸。 好的批注是「点 27 号 V-101，问出口为什么没有止回阀」；不好的批注是「这里感觉不对」。每条批注尽量包含： 热点编号 / 位号； 你看到的现象； 你怀疑的原因或想确认的问题。", "url": "topics/cad/04-review-and-annotate.html#step-3", "status": "active"}, {"topic": "cad", "topicName": "和图纸对话", "audience": "dad", "audienceName": "爸爸", "number": 4, "title": "审图页与批注讨论", "step": "4. 让 Harness 按 handle 回应", "text": "清单适合查数，不适合「看着图说话」。这一讲把一张图变成可缩放、按图层显示、点选实体、写批注的审图页；批注和实体 handle 绑定，讨论时不会脱离图纸。 把清单和导出的批注放在一起： 当前工作区是 CAD-Review/。请只读 inventory/<图号>.json、review/<图号>-notes.json 和 review/<图号>.html，不要修改 original/ 和 dxf/ 里的图纸。 请按 handle 把每条批注对回实体，逐条回答： 1. 这条批注涉及哪个位号、哪条原文、在图纸的哪个位置； 2. 从清单能确认什么； 3. 从清单不能确认什么（需要看原图或做工艺判断的部分）； 4. 值得进一步讨论的两三个问题，按重要性排序。 只提讨论点，不要给工艺结论，不要改图，也不要替我决定哪一版是对的。 对不上 handle 的批注，把热点编号贴回会话再问一次。", "url": "topics/cad/04-review-and-annotate.html#step-4", "status": "active"}, {"topic": "cad", "topicName": "和图纸对话", "audience": "dad", "audienceName": "爸爸", "number": 4, "title": "审图页与批注讨论", "step": "5. 留下讨论记录", "text": "清单适合查数，不适合「看着图说话」。这一讲把一张图变成可缩放、按图层显示、点选实体、写批注的审图页；批注和实体 handle 绑定，讨论时不会脱离图纸。 在 review/<图号>-讨论.md 记录：批注原文、对应 handle 或位号、从清单能确认的事实、仍需原图判断的问题、你的结论或「待定」。 notes/ 记这张图读得对不对； review/ 记这张图讨论出了什么，不要混写。", "url": "topics/cad/04-review-and-annotate.html#step-5", "status": "active"}, {"topic": "cad", "topicName": "和图纸对话", "audience": "dad", "audienceName": "爸爸", "number": 4, "title": "审图页与批注讨论", "step": "检查清单", "text": "清单适合查数，不适合「看着图说话」。这一讲把一张图变成可缩放、按图层显示、点选实体、写批注的审图页；批注和实体 handle 绑定，讨论时不会脱离图纸。 [ ] 至少一张图生成了审图页，能在浏览器打开。 [ ] 缩放、平移、图层勾选都试过。 [ ] 点热点能看到位号、图层和 handle。 [ ] 至少写了一条批注，导出的 JSON 放进了 review/ 。 [ ] Harness 能把每条批注对回具体 handle，且没有编造工艺结论。 [ ] review/<图号>-讨论.md 记下了事实、待确认项和你的判断。 上一讲： 批量台账与跨图核对 · 下一讲： 修改计划与 dry-run 。 备查： dsh-annotate-sync · 工具箱说明", "url": "topics/cad/04-review-and-annotate.html#step-6", "status": "active"}, {"topic": "cad", "topicName": "和图纸对话", "audience": "dad", "audienceName": "爸爸", "number": 5, "title": "修改计划与 dry-run", "step": "1. 修改计划长什么样", "text": "从这一讲开始动图。原则是： 先把改动写成计划，看清差异，再执行 ；执行只写新文件，原图和 DXF 工作副本都不覆盖。 计划是一个 JSON 文件， operations 里每条写清操作、目标 handle、修改前状态（ expect ）和修改后的值。示例见 sample-plan.json ： { \"drawing\": \"sample-pfd.dxf\", \"operations\": [ {\"id\": \"layer-v101\", \"op\": \"set_layer\", \"handle\": \"E4\", \"expect\": {\"type\": \"INSERT\", \"layer\": \"EQUIPMENT\", \"tag\": \"V-101\"}, \"to\": \"EQ-REVIEW\"}, {\"id\": \"name-v101\", \"op\": \"set_attribute\", \"handle\": \"E4\", \"expect\": {\"tag\": \"V-101\", \"name\": \"原料储罐\"}, \"tag\": \"NAME\", \"to\": \"原料罐\"}, {\"id\": \"new-line\", \"op\": \"add_polyline\", \"layer\": \"REVIEW\", \"points\": [[520, 300], [560, 300]]} ] } 支持的操作： op 作用 必填 set_layer 改实体图层 handle 、 expect 、 to move 平移 handle 、 expect 、 delta: [dx, dy] delete 删除 handle 、 expect set_attribute 改块属性 handle 、 expect 、 tag 、 to replace_text 改 TEXT/MTEXT 文字 handle 、 expect 、 to set_color 改 ACI 颜色 handle 、 expect 、 to rename_layer 图层改名 expect 、 from 、 to add_line / add_polyline / add_circle / add_text 新增图元 layer 与几何参数 expect 是守卫：执行前逐条核对当前值；只要有一条与图纸不符，整套计划中止，不写任何文件。", "url": "topics/cad/05-plan-and-dry-run.html#step-1", "status": "active"}, {"topic": "cad", "topicName": "和图纸对话", "audience": "dad", "audienceName": "爸爸", "number": 5, "title": "修改计划与 dry-run", "step": "2. 先检查计划", "text": "从这一讲开始动图。原则是： 先把改动写成计划，看清差异，再执行 ；执行只写新文件，原图和 DXF 工作副本都不覆盖。 .venv-cad/bin/python toolkit/cad.py check-plan plan.json --drawing dxf/<图号>.dxf 输出应列出每条操作的 id 和 handle。任何一条报「找不到 handle」或「守卫不符」，说明清单或图纸已经变了，回到第一讲重新生成清单，不要绕过守卫。", "url": "topics/cad/05-plan-and-dry-run.html#step-2", "status": "active"}, {"topic": "cad", "topicName": "和图纸对话", "audience": "dad", "audienceName": "爸爸", "number": 5, "title": "修改计划与 dry-run", "step": "3. dry-run：只看差异", "text": "从这一讲开始动图。原则是： 先把改动写成计划，看清差异，再执行 ；执行只写新文件，原图和 DXF 工作副本都不覆盖。 .venv-cad/bin/python toolkit/cad.py apply plan.json --drawing dxf/<图号>.dxf --dry-run dry-run 不写文件，只确认计划能通过守卫。把操作逐条对照成自然语言，例如： id 操作 现在的样子 修改后 layer-v101 set_layer E4 / EQUIPMENT / V-101 图层改为 EQ-REVIEW name-v101 set_attribute NAME = 原料储罐 NAME = 原料罐 new-line add_polyline 无 REVIEW 图层新增一段折线 确认三件事：改的对象对不对、改的值对不对、有没有漏掉要改的东西。", "url": "topics/cad/05-plan-and-dry-run.html#step-3", "status": "active"}, {"topic": "cad", "topicName": "和图纸对话", "audience": "dad", "audienceName": "爸爸", "number": 5, "title": "修改计划与 dry-run", "step": "4. 让 Harness 起草计划，但不要执行", "text": "从这一讲开始动图。原则是： 先把改动写成计划，看清差异，再执行 ；执行只写新文件，原图和 DXF 工作副本都不覆盖。 当前工作区是 CAD-Review/。请只读 inventory/<图号>.json 和 dxf/<图号>.dxf 的清单，不要修改任何文件。 我要做的修改是：<用一句话说清，例如「把 V-101 的 NAME 改成原料罐，并把这台设备移到 EQ-REVIEW 图层」>。 请先列出你准备改的实体的 handle、当前值、修改后的值，以及你依据的清单字段。 然后按工具箱 README 的 schema 起草 plan.json，只在会话里展示，不要写入文件，也不要执行 apply。 如果你无法从清单确认某个 handle，写「待确认」，不要猜。 你逐条核对 handle 和当前值，确认后让 Harness 写入 plan.json ；也可以自己改示例文件。", "url": "topics/cad/05-plan-and-dry-run.html#step-4", "status": "active"}, {"topic": "cad", "topicName": "和图纸对话", "audience": "dad", "audienceName": "爸爸", "number": 5, "title": "修改计划与 dry-run", "step": "5. 什么情况下不允许执行", "text": "从这一讲开始动图。原则是： 先把改动写成计划，看清差异，再执行 ；执行只写新文件，原图和 DXF 工作副本都不覆盖。 计划里有你没确认过的 handle； 某条操作会删除实体，但你还没在 AutoCAD 里确认它能删； 计划扩大了范围（比如本来只改一个位号，却顺带改了文字或图层）； 图纸在 AutoCAD 里被另存或改过，清单已经过期。 遇到这些情况，先改计划，不要先执行再回滚。", "url": "topics/cad/05-plan-and-dry-run.html#step-5", "status": "active"}, {"topic": "cad", "topicName": "和图纸对话", "audience": "dad", "audienceName": "爸爸", "number": 5, "title": "修改计划与 dry-run", "step": "检查清单", "text": "从这一讲开始动图。原则是： 先把改动写成计划，看清差异，再执行 ；执行只写新文件，原图和 DXF 工作副本都不覆盖。 [ ] 每条操作都有 handle 和 expect ，没有空守卫。 [ ] check-plan 全部通过。 [ ] dry-run 的对照表逐条看过。 [ ] 删除类操作已在 AutoCAD 里确认。 [ ] 计划范围与口头需求一致，没有顺带改动。 [ ] 还没有写任何文件。 上一讲： 审图页与批注 · 下一讲： 应用、验证与交付 。 备查： sample-plan.json · sample-edit-report.md · 工具箱说明", "url": "topics/cad/05-plan-and-dry-run.html#step-6", "status": "active"}, {"topic": "cad", "topicName": "和图纸对话", "audience": "dad", "audienceName": "爸爸", "number": 6, "title": "应用、验证与交付", "step": "1. 执行到新文件", "text": "最后一讲把修改落到新文件，并且用程序自己验证一遍。目标是：你能拿着报告和 AutoCAD 里的结果，说清「改了什么、没改什么、原件在哪」。 .venv-cad/bin/python toolkit/cad.py apply plan.json \\ --drawing dxf/<图号>.dxf \\ --out work/<图号>-edit-<日期>.dxf 工具会： 再核对一遍每条 expect ； 在内存里执行操作； 另存为新文件（绝不覆盖 dxf/ 或 original/ ）； 重新打开新文件，逐项校验； 在输出文件旁写一份 <输出>.report.md 。", "url": "topics/cad/06-apply-and-verify.html#step-1", "status": "active"}, {"topic": "cad", "topicName": "和图纸对话", "audience": "dad", "audienceName": "爸爸", "number": 6, "title": "应用、验证与交付", "step": "2. 看懂报告", "text": "最后一讲把修改落到新文件，并且用程序自己验证一遍。目标是：你能拿着报告和 AutoCAD 里的结果，说清「改了什么、没改什么、原件在哪」。 报告里有三段： 段落 看什么 输入/输出 sha256 证明改的是副本；输入哈希与原件对应 操作表 每条操作的结果是不是 done 校验表 每条操作是否达成、实体数、未涉及实体是否原样 重点看两条： 实体数 ：修改前 + 新增 − 删除 = 修改后； 未涉及实体保持原样 ：如果列出变化的 handle，说明有预期之外的改动，必须停下来查。 示例报告： sample-edit-report.md 。", "url": "topics/cad/06-apply-and-verify.html#step-2", "status": "active"}, {"topic": "cad", "topicName": "和图纸对话", "audience": "dad", "audienceName": "爸爸", "number": 6, "title": "应用、验证与交付", "step": "3. 在 AutoCAD 里核对", "text": "最后一讲把修改落到新文件，并且用程序自己验证一遍。目标是：你能拿着报告和 AutoCAD 里的结果，说清「改了什么、没改什么、原件在哪」。 打开输出 DXF，先看图层管理器：新图层在不在，改名的图层对不对。 对照报告里的操作表，逐个找到实体：位号、属性、文字、位置。 用审图页复核一次： .venv-cad/bin/python toolkit/cad.py review work/<图号>-edit-<日期>.dxf -o review/<图号>-edit.html 原件和 dxf/ 工作副本的时间和哈希不变。", "url": "topics/cad/06-apply-and-verify.html#step-3", "status": "active"}, {"topic": "cad", "topicName": "和图纸对话", "audience": "dad", "audienceName": "爸爸", "number": 6, "title": "应用、验证与交付", "step": "4. 交付与版本命名", "text": "最后一讲把修改落到新文件，并且用程序自己验证一遍。目标是：你能拿着报告和 AutoCAD 里的结果，说清「改了什么、没改什么、原件在哪」。 输出统一放 work/ ，文件名带日期；不要用「最终版」「最新版」这类名字。 需要 DWG 时，在 AutoCAD 里打开输出 DXF，另存为 DWG；装了 ODA 也可以用 cad.py convert work/xxx.dxf --to dwg 。 交付前把 plan.json 、报告、输出 DXF 和讨论记录放在同一个目录，方便以后追溯。", "url": "topics/cad/06-apply-and-verify.html#step-4", "status": "active"}, {"topic": "cad", "topicName": "和图纸对话", "audience": "dad", "audienceName": "爸爸", "number": 6, "title": "应用、验证与交付", "step": "5. 失败与回退", "text": "最后一讲把修改落到新文件，并且用程序自己验证一遍。目标是：你能拿着报告和 AutoCAD 里的结果，说清「改了什么、没改什么、原件在哪」。 现象 先做什么 「守卫不符」 图纸或清单过期；重新生成 inventory，确认后再生成计划 「找不到 handle」 实体被删或换了文件；不要猜新 handle 校验表「未涉及实体变化」 停下来，查计划范围；可能是图层改名或块属性连带变化 实体数不符 检查新增/删除计数，确认没有重复执行 输出打不开 用原始 DXF 重跑；仍失败就保留输入、计划和报告，记进 notes/ 任何失败都不要回头改原件。输入 DXF、计划、报告和失败的输出都保留，下一次换新文件名重来。", "url": "topics/cad/06-apply-and-verify.html#step-5", "status": "active"}, {"topic": "cad", "topicName": "和图纸对话", "audience": "dad", "audienceName": "爸爸", "number": 6, "title": "应用、验证与交付", "step": "6. 把有效做法留下来", "text": "最后一讲把修改落到新文件，并且用程序自己验证一遍。目标是：你能拿着报告和 AutoCAD 里的结果，说清「改了什么、没改什么、原件在哪」。 跑通一次之后，在 standards/cad-review.md 里补一条可复用的规则，并在 notes/ 记下这次用了哪个计划、哪份报告、哪些 handle。以后同类修改直接套用，不要重新发明。", "url": "topics/cad/06-apply-and-verify.html#step-6", "status": "active"}, {"topic": "cad", "topicName": "和图纸对话", "audience": "dad", "audienceName": "爸爸", "number": 6, "title": "应用、验证与交付", "step": "检查清单", "text": "最后一讲把修改落到新文件，并且用程序自己验证一遍。目标是：你能拿着报告和 AutoCAD 里的结果，说清「改了什么、没改什么、原件在哪」。 [ ] 输出写在 work/ ，文件名带日期。 [ ] 报告里的每条操作都是 done。 [ ] 实体数、未涉及实体两项校验都通过。 [ ] 在 AutoCAD 里看过图层、位号、属性和位置。 [ ] 审图页复核过修改后的图。 [ ] 原件和 dxf/ 工作副本没有被覆盖。 [ ] plan.json 、报告、输出和讨论记录已归档。 上一讲： 修改计划与 dry-run · 回到专题： 和图纸对话 。 备查： 工具箱说明 · sample-edit-report.md", "url": "topics/cad/06-apply-and-verify.html#step-7", "status": "active"}, {"topic": "image-generation", "topicName": "把想法画出来", "audience": "both", "audienceName": "共同", "number": 0, "title": "把想法画出来", "step": "专题介绍", "text": "图片生成与改图 用 Harness 接通图片生成服务，跑通生图、改图和软装方向对比。 ", "url": "topics/image-generation/index.html", "status": "active"}, {"topic": "image-generation", "topicName": "把想法画出来", "audience": "both", "audienceName": "共同", "number": 1, "title": "用 Harness 生成和修改图片", "step": "1. 先分清四个名字", "text": "这一课只做一件事：把「用 DeepSeek Harness 生成图片」这条路跑通。先用虚构的客厅练手，再把自己的房间照片放在本机做软装方向的对比；生成图只当方向板，不当施工图，也不替代商品尺寸和材质核对。 公开课稿只用虚构房间和示例文字；真实家庭照片、门牌、快递单和家人物品只在本机使用，上传前先裁掉隐私信息。 你之前提到的「C Dream」，官方资料写作 Seedream （也见 SeeDream），是字节跳动的图像生成模型。和它相关的几个入口不是一回事： 名称 是什么 这一课怎么用 Seedream / SeeDream 字节跳动 Seed 团队的图像生成模型，支持文生图、参考图生图、局部编辑、组图 本课要调用的模型 即梦 AI 消费端网页/App，使用 Seedream；会员/订阅是消费级入口 可以自己玩，但 不能 直接给 DSH 插件当 API 火山方舟 Ark 火山引擎的模型 API 平台：开通模型、创建 API Key、按量计费 本课必须走这条 dsh-image-gen DeepSeek Harness 的生图插件，支持 Seedream / 火山方舟 Provider 本课安装和配置的插件 关于“订阅” ：即梦会员和火山方舟 API 是两条账本。DSH 插件要的是 Ark API Key，按生成张数计费；不需要先买即梦会员。火山引擎的 Agent Plan 是另一种订阅套餐，可能含部分 Seedream Lite 额度，但先确认它是否提供可用于 /api/v3 的 API Key，不要把它当成图片余额。若只想在网页里随手生成，才考虑即梦会员。", "url": "topics/image-generation/01-generate-and-edit.html#step-1", "status": "active"}, {"topic": "image-generation", "topicName": "把想法画出来", "audience": "both", "audienceName": "共同", "number": 1, "title": "用 Harness 生成和修改图片", "step": "2. 开通火山方舟和 Seedream", "text": "这一课只做一件事：把「用 DeepSeek Harness 生成图片」这条路跑通。先用虚构的客厅练手，再把自己的房间照片放在本机做软装方向的对比；生成图只当方向板，不当施工图，也不替代商品尺寸和材质核对。 公开课稿只用虚构房间和示例文字；真实家庭照片、门牌、快递单和家人物品只在本机使用，上传前先裁掉隐私信息。 打开 火山方舟控制台 ，用爸爸妈妈自己的火山引擎账号登录，按页面要求完成实名认证和开通。 在模型广场或「开通管理」里找到 Seedream ，开通要用的版本。课堂先用 Seedream 5.0 Lite 或 5.0 Pro 试，确认流程后再用 5.5 或更高分辨率。 打开 API Key 管理 ，创建一把只给这台 Mac 用的 Key，命名例如 dsh-image-gen-dad 或 dsh-image-gen-mom 。先停止屏幕共享，由本人复制；Key 不写进聊天、截图或课程仓库。 回到控制台确认计费方式和余额。API 是按量后付费；先在预算里留一小笔练习额度，开启用量/余额提醒。 记下区域和端点。图片生成默认端点是 https://ark.cn-beijing.volces.com/api/v3 ；实际以控制台和插件“拉取模型”结果为准。 当前常见模型 ID（以控制台/插件拉取结果为准）： doubao-seedream-5-5-261028 ：Seedream 5.5，2026-11-09 发布，API 陆续开放； doubao-seedream-5-0-pro-260628 ：Seedream 5.0 Pro，插件当前默认之一； doubao-seedream-5-0-260128 / doubao-seedream-5-0-lite-260128 ：Seedream 5.0 Lite。 价格示例（2026-11-15 查到的官方口径，实际以下单页面为准）：Seedream 5.0 Pro 输出图不超过 236 万像素约 0.3 元/张，更大尺寸约 0.6 元/张；5.5 约 0.28 元/2K 方图编辑；Lite 更便宜。先用 Lite/1K 试构图，满意后用 Pro/5.5/2K。", "url": "topics/image-generation/01-generate-and-edit.html#step-2", "status": "active"}, {"topic": "image-generation", "topicName": "把想法画出来", "audience": "both", "audienceName": "共同", "number": 1, "title": "用 Harness 生成和修改图片", "step": "3. 安装并启用 dsh-image-gen", "text": "这一课只做一件事：把「用 DeepSeek Harness 生成图片」这条路跑通。先用虚构的客厅练手，再把自己的房间照片放在本机做软装方向的对比；生成图只当方向板，不当施工图，也不替代商品尺寸和材质核对。 公开课稿只用虚构房间和示例文字；真实家庭照片、门牌、快递单和家人物品只在本机使用，上传前先裁掉隐私信息。 打开 DeepSeek Harness 左侧的「插件」面板，进入「已安装」或插件市场，搜索 dsh-image-gen 。 安装或启用后重启 Harness。插件详情页应出现「图像生成」配置表单；输入框旁也会出现生图按钮。 不要照搬插件 README 里的 --profile web 命令到 Desktop；父母用界面安装即可。若界面找不到，先确认 Harness 版本，再让家人协助用插件管理。 安装只需一次；以后升级插件后重新打开详情页检查 Provider 和模型是否还在。", "url": "topics/image-generation/01-generate-and-edit.html#step-3", "status": "active"}, {"topic": "image-generation", "topicName": "把想法画出来", "audience": "both", "audienceName": "共同", "number": 1, "title": "用 Harness 生成和修改图片", "step": "4. 配置 Seedream Provider", "text": "这一课只做一件事：把「用 DeepSeek Harness 生成图片」这条路跑通。先用虚构的客厅练手，再把自己的房间照片放在本机做软装方向的对比；生成图只当方向板，不当施工图，也不替代商品尺寸和材质核对。 公开课稿只用虚构房间和示例文字；真实家庭照片、门牌、快递单和家人物品只在本机使用，上传前先裁掉隐私信息。 在插件详情页： 默认 Provider 选 ByteDance Seedream / 火山方舟 （界面可能显示「字节 Seedream」）。 填入第 2 步创建的 API Key。 Endpoint / Base URL 保持默认；若为空，填 https://ark.cn-beijing.volces.com/api/v3 。 模型先填 doubao-seedream-5-0-pro-260628 ，或点「拉取模型」后选可用的 5.5 / 5.0 Lite。 点「测试连接」。通过后再点「拉取模型」核对模型列表；失败先看第 8 步的排错。 设置输出格式（PNG/JPEG）、水印开关和保存工作区。水印是否可关以模型和条款为准；课堂先用默认。 保存后，回到会话输入框旁确认 Provider 是 Seedream，不要误用 ChatGPT 订阅通道。 密钥只保存在本机 DSH 凭据里；不要为了“方便”把 Key 写进课稿、仓库、聊天或截图。", "url": "topics/image-generation/01-generate-and-edit.html#step-4", "status": "active"}, {"topic": "image-generation", "topicName": "把想法画出来", "audience": "both", "audienceName": "共同", "number": 1, "title": "用 Harness 生成和修改图片", "step": "5. 第一张图：虚构客厅", "text": "这一课只做一件事：把「用 DeepSeek Harness 生成图片」这条路跑通。先用虚构的客厅练手，再把自己的房间照片放在本机做软装方向的对比；生成图只当方向板，不当施工图，也不替代商品尺寸和材质核对。 公开课稿只用虚构房间和示例文字；真实家庭照片、门牌、快递单和家人物品只在本机使用，上传前先裁掉隐私信息。 先用一张虚构房间练提示词，不要上传真实家庭照片。要求写明：房间、固定不动的元素、要换的软装、光线、镜头和比例。 请生成一张约 20 平方米客厅的软装示意：浅橡木地板，米白色墙，左侧落地窗，午后自然光；现有灰色布艺三人沙发、白色圆形茶几。请只把沙发换成浅米色亚麻三人沙发，增加胡桃木边柜和橄榄绿地毯；保留窗、墙、地板、光线和拍摄角度不变，其他家具不要移动。真实照片感，24mm 广角，1:1，不要添加文字。 生成后先看四件事： 房间结构和窗/墙/地板有没有被改掉； 沙发、边柜、地毯是不是你要的方向； 光线、镜头角度是否还能和原房间对上； 画面里有没有乱码文字或多余物件。 不要一次要求“全部重新设计”。软装对比要控制变量，否则看不出是哪一件东西变了。", "url": "topics/image-generation/01-generate-and-edit.html#step-5", "status": "active"}, {"topic": "image-generation", "topicName": "把想法画出来", "audience": "both", "audienceName": "共同", "number": 1, "title": "用 Harness 生成和修改图片", "step": "6. 在原图上改：只换一处", "text": "这一课只做一件事：把「用 DeepSeek Harness 生成图片」这条路跑通。先用虚构的客厅练手，再把自己的房间照片放在本机做软装方向的对比；生成图只当方向板，不当施工图，也不替代商品尺寸和材质核对。 公开课稿只用虚构房间和示例文字；真实家庭照片、门牌、快递单和家人物品只在本机使用，上传前先裁掉隐私信息。 打开 画廊 → 工作台 ，或在画布/图库里选中刚生成的图： 点「继续编辑（垫图）」或把图拖进画布，作为参考图。 用画笔圈出要改的区域（例如沙发），或在提示词里明确位置。 发一条只改一处的修改意见： 只改左侧沙发：换成浅米色亚麻三人沙发；保留窗帘、地板、光线、镜头角度、其他家具和房间结构不变。不要把整张图重新设计，不要添加文字。 生成后对比新旧两版，满意就保存为新版本；不满意就退回上一版再改，不要覆盖原图。 再试一次“只换地毯”或“只换落地灯”，每次都只改一个变量。 如果插件支持画布选区，优先圈出要改的地方再发指令；选区能让模型更清楚“只改这里”。如果当前通道的图生图不稳定，就先退回“文字重生成”，但把固定条件写得更具体。", "url": "topics/image-generation/01-generate-and-edit.html#step-6", "status": "active"}, {"topic": "image-generation", "topicName": "把想法画出来", "audience": "both", "audienceName": "共同", "number": 1, "title": "用 Harness 生成和修改图片", "step": "7. 软装选品：三套方案与核对", "text": "这一课只做一件事：把「用 DeepSeek Harness 生成图片」这条路跑通。先用虚构的客厅练手，再把自己的房间照片放在本机做软装方向的对比；生成图只当方向板，不当施工图，也不替代商品尺寸和材质核对。 公开课稿只用虚构房间和示例文字；真实家庭照片、门牌、快递单和家人物品只在本机使用，上传前先裁掉隐私信息。 同一房间一次生成三套方向，每套只改变软装组合： 同一间客厅，保留墙、窗、地板、主沙发、光线和镜头角度不变，分别生成三套软装方向： A：橄榄绿地毯 + 藤编落地灯 + 胡桃木边几； B：米色羊毛地毯 + 黑色细杆落地灯 + 浅木边柜； C：蓝灰地毯 + 黄铜落地灯 + 深色边几。 每套单独一张图，真实照片感，1:1，不要添加文字。 拿去淘宝/店里选品时： 先量墙面、沙发、柜子和通道尺寸，再看商品尺寸；生成图不保证比例。 用生成图比较颜色、材质和风格，商品页的尺寸、材质、色差、安装方式和退货政策以商家为准。 不要根据生成图判断“放得下”；放不下是尺寸问题，不是画面问题。 真实房间照片只在本机使用；上传前裁掉门牌、家人照片、快递单等隐私信息；公开课稿只放虚构房间。 生成图只作方向板，最终以实物、样板和小样为准。", "url": "topics/image-generation/01-generate-and-edit.html#step-7", "status": "active"}, {"topic": "image-generation", "topicName": "把想法画出来", "audience": "both", "audienceName": "共同", "number": 1, "title": "用 Harness 生成和修改图片", "step": "8. 费用、隐私和故障排查", "text": "这一课只做一件事：把「用 DeepSeek Harness 生成图片」这条路跑通。先用虚构的客厅练手，再把自己的房间照片放在本机做软装方向的对比；生成图只当方向板，不当施工图，也不替代商品尺寸和材质核对。 公开课稿只用虚构房间和示例文字；真实家庭照片、门牌、快递单和家人物品只在本机使用，上传前先裁掉隐私信息。 费用 按生成张数计费；先 Lite/1K 试构图，再用 Pro/5.5/2K 做最终图。 在火山方舟控制台看用量、余额和账单；设预算提醒，避免一次批量生成过多。 5.0 Pro 输出图 ≤236 万像素约 0.3 元/张，更大尺寸约 0.6 元/张；5.5 约 0.28 元/2K 编辑；以控制台为准。 隐私 API Key 不截图、不进聊天、不进仓库；只放本机 DSH 凭据。 真实家庭照片不上传公开仓库；按火山方舟条款处理图片。 课堂投屏时先停共享再粘贴 Key。 排错 现象 先检查 401/403 Key 是否复制完整；模型是否开通；账号是否欠费；实名/区域是否符合 404 模型不存在 模型 ID 是否过期；点「拉取模型」选当前 ID；5.5 是否已对该账号开放 429 触发限流；等一会儿，减少并发/批量 测试连接失败 Endpoint 是否 /api/v3 ；Key 是否属于当前区域；网络是否可访问火山方舟 生成成功但看不到图 图库/工作区保存位置；Provider 是否选对；刷新或重开插件 中文小字乱码 减少画面文字；重要文字后期另加，不依赖模型写小字 改图改得太多 提示词写“只改…、保留…”，用选区圈定；降低一次修改数量", "url": "topics/image-generation/01-generate-and-edit.html#step-8", "status": "active"}, {"topic": "image-generation", "topicName": "把想法画出来", "audience": "both", "audienceName": "共同", "number": 1, "title": "用 Harness 生成和修改图片", "step": "9. 验收清单", "text": "这一课只做一件事：把「用 DeepSeek Harness 生成图片」这条路跑通。先用虚构的客厅练手，再把自己的房间照片放在本机做软装方向的对比；生成图只当方向板，不当施工图，也不替代商品尺寸和材质核对。 公开课稿只用虚构房间和示例文字；真实家庭照片、门牌、快递单和家人物品只在本机使用，上传前先裁掉隐私信息。 [ ] 能说清 Seedream、即梦、火山方舟和 dsh-image-gen 的区别。 [ ] 火山方舟账号已开通 Seedream，API Key 只保存在本机。 [ ] dsh-image-gen 已安装并启用，Provider 选 ByteDance Seedream / 火山方舟。 [ ] 「测试连接」通过，「拉取模型」能看到可用模型。 [ ] 用虚构客厅生成至少一张图，能说出模型、尺寸和大约费用。 [ ] 在原图上只改一处（沙发/地毯/灯），保存新版本，原图还在。 [ ] 生成三套软装方向，能说清哪些是画面方向、哪些必须去商品页核对尺寸和材质。 [ ] 真实照片没有上传公开仓库；API Key 没有进截图、聊天或课稿。 备查 Seedream 5.5 教程 Seedream 5.0 Pro 教程 图片生成教程 模型价格 API Key 管理 dsh-image-gen 插件", "url": "topics/image-generation/01-generate-and-edit.html#step-9", "status": "active"}, {"topic": "version-control", "topicName": "版本管理与协作", "audience": "both", "audienceName": "共同", "number": 0, "title": "版本管理与协作", "step": "专题介绍", "text": "用 GitHub 管好文件和改动 注册 GitHub，建立私有仓库，把练习文件提交、推送并在本机找回。 ", "url": "topics/version-control/index.html", "status": "active"}, {"topic": "version-control", "topicName": "版本管理与协作", "audience": "both", "audienceName": "共同", "number": 1, "title": "第一次把文件放进 GitHub 仓库", "step": "1. 各自注册并登录", "text": "两人在自己的 Mac 上打开 GitHub 注册页 ，各自注册个人账号，按网页提示完成邮箱验证。登录后点右上角头像，确认用户名是自己的。登录、验证码和授权由本人完成，遇到卡点先停下来一起看。 GitHub 账号注册说明", "url": "topics/version-control/01-first-repository.html#step-1", "status": "active"}, {"topic": "version-control", "topicName": "版本管理与协作", "audience": "both", "audienceName": "共同", "number": 1, "title": "第一次把文件放进 GitHub 仓库", "step": "2. 新建仓库时，先看可见性", "text": "各自打开 新建 GitHub 仓库 ，确认 Owner 是自己的账号。爸爸可取名 technical-manual ，妈妈可取名 my-first-repo 。课堂先选 Private ，创建后检查仓库名称旁是否显示 Private。 选项 谁能看到 Private（私有） 自己和获授权的人。爸爸的手册和妈妈的小项目先用这个选项。 Public（公开） 任何人都可以查看仓库里的文件和公开提交历史。以后要公开自己的小项目时，再一起核对素材和发布范围。 私有仓库里也只放有权上传的文件。手册先选已确认可上传的 .tex 、Markdown 规则和示例图表。账号信息、密钥、无权上传的内部资料留在本机。妈妈先用自己的一组虚构练习文件。 GitHub 仓库可见性说明", "url": "topics/version-control/01-first-repository.html#step-2", "status": "active"}, {"topic": "version-control", "topicName": "版本管理与协作", "audience": "both", "audienceName": "共同", "number": 1, "title": "第一次把文件放进 GitHub 仓库", "step": "3. 认三个词，让 Harness 帮忙执行", "text": "本节默认已经装好 DeepSeek Harness（先完成「和 AI 一起做事」第 2 讲）。 clone（克隆） ：把 GitHub 仓库复制到电脑，得到可以编辑的本地项目。 commit（提交） ：在本地保存一份带说明的版本记录。 push（推送） ：把已提交的版本送到指定的 GitHub 仓库。 在新仓库复制地址。各自在 Mac 选一个空练习位置，让 Harness 把仓库克隆到那里。若 GitHub 要求本机登录或授权，按提示由本人完成，再让 Harness 继续。 打开克隆得到的文件夹。爸爸复制选好的手册文件，妈妈复制自己的 index.html 或那节课用到的练习文件。原来的本地项目仍可直接打开。复制前先看仓库里有没有 .gitignore ；没有就建一个，至少排除 .DS_Store 、密钥文件和私人草稿。 用自然语言交代任务。先让 Harness 列出要上传的内容，自己检查后再同意推送。若 Harness 不能直接执行 git，就让它给出命令，由本人打开「终端」逐条执行并核对输出。 这个本地文件夹来自我刚建立的私有 GitHub 仓库。请核对远端地址和仓库所有者，列出准备提交的文件、分支和提交说明。只提交我刚复制进去、确认可上传的项目文件。不要提交密钥、账号资料或私人原件。等我确认后再提交和推送。需要登录或权限时先停下来告诉我。 回到浏览器刷新各自的仓库，检查仍显示 Private，文件和提交说明都出现了。爸爸打开一份手册源文件，妈妈打开 index.html 。看得见文件，就完成了第一次推送。 克隆仓库 · 提交和推送入门 本节只练文件推送。以后要让家人从网址打开自己的页面时，再单独配置 GitHub Pages 和确认发布范围。 GitHub Pages 说明", "url": "topics/version-control/01-first-repository.html#step-3", "status": "active"}, {"title": "办公室白板上的画", "heading": "拾趣", "text": "我的妻子赵诗雅博士（Dr Shiya Zhao，Kyoto University & IIASA） ChatGPT 生成 Kyoto University & IIASA zhao.shiya.j46@kyoto-u.jp 南丹麦大学（SDU）办公室 白板笔、白板", "url": "gallery/whiteboard.html#gallery", "route": "gallery", "routeName": "拾趣", "lesson": null, "status": "active"}];
